//openpresentation.org/schema/opf-chart-type/v1",id:"treemap-2x",name:"TREEMAP_2X",label:"Treemap 2x",mappings:{openxml:{element:"treemapChart",composition:"extension",notes:"Office extension chart; exact extension markup is renderer-specific."}},categories:6,columns:["Level1","Level2","Series1"],group:"Treemap",groupSort:8,series:1,seriesGroups:1,slideNumber:44,useSecondaryCategories:!1,workbookRange:"Sheet1!$A$1:$G$3",complexity:"hierarchical",dataColumns:[{name:"Level1",role:"categoryLabel",type:"string",position:"row0_col0"},{name:"Level2",role:"series",type:"number",position:"row1_col0"},{name:"Series1",role:"series",type:"number",position:"row2_col0"}],sampleData:{headers:["Level1","Level2","Value"],rows:[["Technology","Software",96],["Technology","Hardware",99],["Technology","Services",48],["Finance","Banking",86],["Finance","Insurance",68],["Healthcare","Pharma",77],["Healthcare","Devices",76]]}},{$schema:"https://openpresentation.org/schema/opf-chart-type/v1",id:"treemap-3x",name:"TREEMAP_3X",label:"Treemap 3x",mappings:{openxml:{element:"treemapChart",composition:"extension",notes:"Office extension chart; exact extension markup is renderer-specific."}},categories:16,columns:["Level1","Level2","Level3","Series1"],group:"Treemap",groupSort:8,series:1,seriesGroups:1,slideNumber:45,useSecondaryCategories:!1,workbookRange:"Sheet1!$A$1:$Q$4",complexity:"hierarchical",dataColumns:[{name:"Level1",role:"categoryLabel",type:"string",position:"row0_col0"},{name:"Level2",role:"helper",type:"number",position:"row1_col0"},{name:"Level3",role:"series",type:"number",position:"row2_col0"},{name:"Series1",role:"series",type:"number",position:"row3_col0"}],sampleData:{headers:["Level1","Level2","Level3","Value"],rows:[["North","Tech","Software",58],["North","Tech","Hardware",95],["North","Finance","Banking",74],["North","Finance","Insurance",59],["South","Tech","Software",92],["South","Tech","Hardware",99],["South","Finance","Banking",27],["South","Finance","Insurance",98]]}},{$schema:"https://openpresentation.org/schema/opf-chart-type/v1",id:"united-kingdom",name:"UNITED_KINGDOM",label:"United Kingdom",mappings:{openxml:{element:"mapChart",composition:"extension",notes:"Office extension chart; exact extension markup is renderer-specific."}},categories:4,columns:["State","Value"],group:"Map",groupSort:12,series:1,seriesGroups:1,slideNumber:69,useSecondaryCategories:!1,workbookRange:"Sheet1!$A$1:$E$2",complexity:"simple",dataColumns:[{name:"State",role:"categoryLabel",type:"string",position:"row0_col0"},{name:"Value",role:"series",type:"number",position:"row1_col0"}],sampleData:{headers:["State","Q1 2024","Q2 2024","Q3 2024","Q4 2024"],rows:[["Value",33218,92306,74764,70811]]}},{$schema:"https://openpresentation.org/schema/opf-chart-type/v1",id:"united-states",name:"UNITED_STATES",label:"United States",mappings:{openxml:{element:"mapChart",composition:"extension",notes:"Office extension chart; exact extension markup is renderer-specific."}},categories:11,columns:["State","Value"],group:"Map",groupSort:12,series:1,seriesGroups:1,slideNumber:67,useSecondaryCategories:!1,workbookRange:"Sheet1!$A$1:$L$2",complexity:"simple",dataColumns:[{name:"State",role:"categoryLabel",type:"string",position:"row0_col0"},{name:"Value",role:"series",type:"number",position:"row1_col0"}],sampleData:{headers:["State","Q1 2024","Q2 2024","Q3 2024","Q4 2024","Q1 2025","Q2 2025","Q3 2025","Q4 2025","Q1 2026","Q2 2026","Q3 2026"],rows:[["Value",39041,53655,32037,20011,76910,92998,24945,79547,76840,35415,55793]]}},{$schema:"https://openpresentation.org/schema/opf-chart-type/v1",id:"waterfall",name:"WATERFALL",label:"Waterfall",mappings:{openxml:{element:"waterfallChart",composition:"extension",notes:"Office extension chart; exact extension markup is renderer-specific."}},categories:8,columns:["Category","Series1"],group:"Other",groupSort:13,series:1,seriesGroups:1,slideNumber:74,useSecondaryCategories:!1,workbookRange:"Sheet1!$A$1:$I$2",complexity:"simple",dataColumns:[{name:"Category",role:"categoryLabel",type:"string",position:"row0_col0"},{name:"Series1",role:"series",type:"number",position:"row1_col0"}],sampleData:{headers:["Category","Q1 2024","Q2 2024","Q3 2024","Q4 2024","Q1 2025","Q2 2025","Q3 2025","Q4 2025"],rows:[["Series1",88282,59377,30218,31266,33703,91885,31697,67366]]}},{$schema:"https://openpresentation.org/schema/opf-chart-type/v1",id:"world",name:"WORLD",label:"World",mappings:{openxml:{element:"mapChart",composition:"extension",notes:"Office extension chart; exact extension markup is renderer-specific."}},categories:14,columns:["Country","Value"],group:"Map",groupSort:12,series:1,seriesGroups:1,slideNumber:66,useSecondaryCategories:!1,workbookRange:"Sheet1!$A$1:$O$2",complexity:"simple",dataColumns:[{name:"Country",role:"categoryLabel",type:"string",position:"row0_col0"},{name:"Value",role:"series",type:"number",position:"row1_col0"}],sampleData:{headers:["Country","Cat 1","Cat 2","Cat 3","Cat 4","Cat 5","Cat 6","Cat 7","Cat 8","Cat 9","Cat 10","Cat 11","Cat 12","Cat 13","Cat 14"],rows:[["Value",70305,57428,21551,67240,23875,41891,67104,87184,62487,78676,20308,61873,50668,54500]]}}],Cl=[{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"problem-solution",name:"Problem \u2192 Solution",summary:"Classic business arc: name the pain, raise the stakes, present your fix, show how it works, prove it, ask. The default for sales decks, internal proposals, and most general business presentations.",audienceFit:["customers","stakeholders","executives","internal-teams"],durationRange:{minMinutes:5,maxMinutes:30},tags:["business","sales","general","proposal"],beats:[{id:"hook",name:"Hook",description:"Open with a striking question, statistic, customer quote, or moment that earns the audience's attention. The goal is to make them want to hear what comes next, not to convey information.",layoutHint:"title-center"},{id:"problem",name:"The Problem",description:"Name the pain in concrete terms. Make it visceral and specific \u2014 describe who hurts, how, and what they're trying to do today that isn't working. Avoid abstractions; use real examples or scenarios the audience recognizes."},{id:"stakes",name:"Why It Matters",description:"Quantify the cost of inaction or the upside of action. Use numbers, trends, customer impact, competitive pressure \u2014 whatever makes the audience feel the size of the problem and care about solving it now rather than later."},{id:"solution",name:"The Solution",description:"Reveal your approach and what it produces for the customer. Lead with the outcome, not the architecture. Keep it concrete: what does the audience get, and what changes for them?"},{id:"mechanism",name:"How It Works",description:"Show the moving parts that make the solution credible. Walk through the key mechanism, workflow, or technical insight that explains why this approach succeeds where others have failed. Enough detail to earn trust; not so much that you lose the room."},{id:"evidence",name:"Proof",description:"Demonstrate the solution works. Use customer logos, before/after metrics, demos, case studies, third-party validation \u2014 whatever de-risks the claim. One strong piece of proof beats three weak ones."},{id:"ask",name:"The Ask",description:"State a clear, specific call to action. What do you want the audience to do, decide, or commit to next? Make the smallest credible ask that moves things forward, and make it unambiguous.",layoutHint:"title-left"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"scqa",name:"SCQA (Situation\u2013Complication\u2013Question\u2013Answer)",summary:"Barbara Minto's pyramid-principle arc: surface the recommendation up front, then layer key arguments and supporting evidence beneath it. The default for executive memos, strategic recommendations, and consulting decks where the audience needs the answer fast.",audienceFit:["executives","boards","leadership-teams"],durationRange:{minMinutes:5,maxMinutes:20},tags:["executive","strategy","consulting","minto","pyramid"],beats:[{id:"situation",name:"Situation",description:"Establish the shared context: what is true today that the audience already agrees on. State only facts the audience accepts without argument. The goal is alignment, not persuasion \u2014 you are setting the stage."},{id:"complication",name:"Complication",description:"Introduce the disturbance to the situation: what changed, what is at risk, what is no longer working. This is the tension that makes the audience lean in. Be specific and quantify the change where possible."},{id:"question",name:"Key Question",description:"Surface the question the complication forces the audience to answer. Frame it explicitly \u2014 'Should we\u2026?', 'How do we\u2026?', 'What changes if\u2026?'. The question should feel inevitable given the complication."},{id:"answer",name:"Answer",description:"Deliver the recommendation in a single sentence, up front. No arguments yet, no caveats \u2014 just the conclusion the rest of the deck will defend. This is the apex of the Minto pyramid; everything that follows supports it.",layoutHint:"title-left"},{id:"key-arguments",name:"Key Arguments",description:"Lay out the two or three top-level reasons the answer is correct. One slide per argument, or one summary slide naming all of them. Each argument should stand alone as a compelling reason; together they should be exhaustive of the case."},{id:"supporting-evidence",name:"Supporting Evidence",description:"Present the data, examples, and case studies that ground each argument. Pyramid-principle style: every claim above is backed by something verifiable here. Cite sources; show the numbers; let the evidence carry the weight."}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"strategic-narrative",name:"Strategic Narrative",summary:"The change-driven founder/sales arc: a tectonic shift creates winners and losers, the audience must respond, and your product is the only credible way to land in the winners' camp. Used for top-of-funnel sales pitches, board re-positioning, and high-stakes founder talks.",audienceFit:["customers","prospects","board","investors","executives"],durationRange:{minMinutes:10,maxMinutes:30},tags:["strategic","sales","positioning","category"],beats:[{id:"shift",name:"The Shift",description:"Open by naming a large, undeniable change in the world that the audience already half-believes. Technology, regulation, customer behavior, economics \u2014 pick the shift that recasts the audience's reality. The shift, not your product, is the protagonist of the first half of the deck."},{id:"stakes",name:"Winners and Losers",description:"Make the consequences of the shift concrete. Who wins, who loses, by how much, on what timeframe. Use specific examples \u2014 companies, products, segments \u2014 that have already moved or are about to. The audience should feel that standing still is the riskiest choice."},{id:"promised-land",name:"Promised Land",description:"Paint a vivid picture of the future state your audience could occupy if they navigate the shift well. Describe outcomes, not features. The promised land must feel desirable, achievable, and meaningfully different from where they are today."},{id:"obstacles",name:"Old Game",description:"Show why the existing playbook can't get the audience to the promised land. Name the legacy approach honestly and credit what it once did, then explain why the shift has rendered it insufficient. Avoid strawmen \u2014 the more fairly you state the old game, the more credible your new game becomes."},{id:"mechanism",name:"New Game",description:"Introduce your category-defining approach as the way to play the new game. Show the principles or capabilities that make it possible only now. Emphasize what's structurally different from the old game, not what's marginally better."},{id:"evidence",name:"Evidence",description:"Prove the new game works. Customer outcomes, named logos, before/after data, third-party validation. Choose evidence that maps directly to the shift you opened with \u2014 proof that other audiences in the same boat made it to the promised land."},{id:"ask",name:"Call to Action",description:"Close with the single decision you want the audience to make. Frame it as the obvious next move given the shift, the stakes, and the new game. Make it small enough to say yes to today and large enough to start a real engagement.",layoutHint:"title-left"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"golden-circle",name:"Golden Circle (Why / How / What)",summary:"Simon Sinek's keynote arc: lead with belief, follow with method, finish with proof. Best for brand stories, mission-driven keynotes, and any deck where the audience needs to feel why before they can evaluate what.",audienceFit:["customers","employees","general-audience","press"],durationRange:{minMinutes:10,maxMinutes:30},tags:["keynote","brand","mission","sinek"],beats:[{id:"why",name:"Why",description:"Open with the belief or purpose that animates the work. Why does this exist, and why should anyone care beyond commerce? State it plainly and emotionally \u2014 the why is meant to be felt before it is understood."},{id:"how",name:"How",description:"Translate the belief into the principles that guide how you operate. The values, decisions, and trade-offs that make your approach distinctive. The 'how' is what people who share your why recognize as familiar."},{id:"what",name:"What",description:"Show the products, services, or outputs that the why and how produce. Concrete examples, not abstractions. The what is the artifact of the belief \u2014 proof that the why is more than rhetoric."},{id:"proof",name:"Proof",description:"Demonstrate the impact in lives, customers, or outcomes. Stories beat statistics here; specific people and moments earn the audience's belief better than aggregate numbers. End with proof that what you do works because of why you do it."},{id:"invitation",name:"Invitation",description:"Close by inviting the audience to share the belief \u2014 to buy, build, join, or evangelize. The strongest invitations don't argue; they assume alignment and offer a way in.",layoutHint:"title-left"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"conference-talk",name:"Conference Talk",summary:"Stage-talk arc for a 15\u201345 minute conference or industry-event session: hook the room, promise a payoff, deliver evidence, expose the underlying mechanism, show how to apply it, and end with a memorable recap. Engineered for audiences that came to learn something they can use Monday.",audienceFit:["practitioners","general-audience","industry-peers"],durationRange:{minMinutes:15,maxMinutes:45},tags:["talk","conference","keynote","education"],beats:[{id:"hook",name:"Hook",description:"Earn the first sixty seconds with a story, surprising claim, or vivid moment. Make the audience curious enough to put their phones down. Avoid agendas, bios, and 'today I'm going to talk about' openings \u2014 those are filler that competes with your real opening."},{id:"promise",name:"Promise",description:"Tell the audience exactly what they'll know, feel, or be able to do by the end of the talk. A clear promise sets the implicit contract for the next thirty minutes and lets you redirect attention later when needed."},{id:"evidence",name:"Evidence",description:"Deliver the substantive case for your promise. Data, examples, demonstrations, or strong stories \u2014 whatever a skeptical attendee would need to update their beliefs. This is the densest section of the talk; pace and visualize accordingly."},{id:"mechanism",name:"Mechanism",description:"Reveal the underlying principle or framework that explains why the evidence holds. The mechanism is what audiences quote later \u2014 the moment of 'oh, that's why.' Keep it crisp and namable."},{id:"application",name:"Application",description:"Show the audience how to use the mechanism in their own work. Concrete, specific, low-friction first steps. The talk earns its keep here \u2014 abstract insight without an applied path is forgotten by lunch."},{id:"recap",name:"Recap",description:"Restate the promise, the mechanism, and the call to action in a single short slide. Give the audience the line they'll repeat to a colleague and the one image that will stick with them after the lights come up.",layoutHint:"title-left"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"transformation-arc",name:"Transformation Arc (Before / After / Bridge)",summary:"Marketing-copy arc adapted for slides: paint the painful 'before,' contrast it with a vivid 'after,' then deliver the bridge that gets the audience from one to the other. Tight, persuasive, and ideal for short pitches, landing-page-style decks, and product-marketing teasers.",audienceFit:["customers","prospects","marketing-teams","general-audience"],durationRange:{minMinutes:3,maxMinutes:15},tags:["marketing","copywriting","pitch","persuasive"],beats:[{id:"before",name:"Before",description:"Describe the audience's current world in the first person they recognize. Specific frustrations, specific costs, specific moments of friction. The clearer the 'before' lands, the more the rest of the deck has to push against."},{id:"after",name:"After",description:"Paint the world the audience could be in instead. Concrete outcomes, not feature lists \u2014 what a day looks like, what a quarter feels like, what becomes effortless that used to hurt. Make it desirable and credible at the same time."},{id:"bridge",name:"Bridge",description:"Show the path from before to after: the product, service, or change that closes the gap. Lead with the simplest user-visible thing they do; the architecture can wait. The bridge must feel proportionate to the transformation it promises."},{id:"evidence",name:"Evidence",description:"Prove the bridge has carried others across. One or two strong customer stories, before/after metrics, or named logos with concrete outcomes. Choose proof that maps directly to the 'after' you painted, not generic credibility markers."},{id:"ask",name:"Ask",description:"Close with the single low-friction action that starts the audience across the bridge. Make it small enough to act on now and meaningful enough to count as commitment.",layoutHint:"title-left"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"pitch-deck",name:"Startup Pitch Deck",summary:"The canonical investor-pitch arc, drawn from Sequoia and Y Combinator's templates. Optimized for 10\u201320 minute meetings with VCs and angels. Each beat answers the question an investor will ask next.",audienceFit:["investors","venture-capitalists","angels","advisors"],durationRange:{minMinutes:10,maxMinutes:20},tags:["startup","fundraising","pitch","investor"],beats:[{id:"opening",name:"Opening",description:"Open with the company name, logo, and a one-line tagline that doubles as a positioning statement. Set the visual tone for the deck. Keep it confident and uncluttered \u2014 this is the cover.",layoutHint:"title-left"},{id:"purpose",name:"Company Purpose",description:"State in a single sentence what the company does and why it exists. Should be immediately understandable without industry jargon. Often doubles as the answer to 'so what do you do?'"},{id:"problem",name:"Problem",description:"Describe the pain point you solve. Make it concrete with a specific user or customer scenario. The more visceral and recognizable the problem, the stronger the rest of the pitch lands."},{id:"why-now",name:"Why Now",description:"Explain the technological, regulatory, behavioral, or market shift that makes this opportunity possible today and impossible five years ago. Investors want to know why this is a window, not just an idea."},{id:"market",name:"Market Size",description:"Size the opportunity. Top-down (TAM/SAM/SOM) or bottom-up (units \xD7 price). Show how big the prize is if you win, and why this market is attractive to a venture-scale outcome."},{id:"competition",name:"Competition",description:"Map the competitive landscape honestly. A 2x2 matrix or feature-comparison grid is fine; what matters is showing you understand the alternatives and where you uniquely fit. Na\xEFve 'no competition' answers tank credibility."},{id:"solution",name:"Solution",description:"Show how you solve the problem and why your approach is uniquely better. Lead with the outcome for the customer, then show the mechanism. This is where you connect problem to product."},{id:"product",name:"Product",description:"Give the product its own moment. Screenshots or a key visual that captures what users actually see and feel. Pick one strong frame over a montage of small ones."},{id:"demo",name:"Demo",description:"Walk through the core user flow end-to-end. Show real software solving a real problem in a real workflow \u2014 not a marketing reel. If a live demo is too risky, use a tightly edited recording with narration."},{id:"traction",name:"Traction",description:"Prove momentum with one credible headline metric. Revenue, users, growth rate, customer logos \u2014 whatever best shows the business is working. One strong chart beats five vanity numbers."},{id:"growth",name:"Growth Drivers",description:"Show how the headline metric got there and where it's going. Cohorts, retention, expansion, channel mix \u2014 whatever explains the engine behind the number. Investors back the trajectory, not the snapshot."},{id:"business-model",name:"Business Model",description:"Explain how the company makes money. Pricing, unit economics, sales motion, payback period. Should answer: what does it cost to acquire a customer, and what do they pay you?"},{id:"team",name:"Team",description:"Establish why this team uniquely wins this market. Founder backgrounds, relevant experience, prior outcomes, key advisors. Investors back people first; make the case."},{id:"financials",name:"Financials",description:"Show the financial picture: historical revenue, burn, runway, and forward projection. Be conservative-but-credible \u2014 investors will discount aggressive numbers and reward defensible ones."},{id:"ask",name:"The Ask",description:"State the round size, intended use of funds, and what milestones the capital takes you to. Be specific \u2014 investors should leave knowing exactly what you want and what they get.",layoutHint:"title-left"},{id:"closing",name:"Closing",description:"Close on a strong final image: logo, contact info, and the one line you most want the investor to remember. Leave space for the conversation that follows.",layoutHint:"title-left"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"early-startup-pitch",name:"Early-Stage Startup Pitch",summary:"Seed and pre-seed pitch arc tuned for vision-heavy stories where revenue and traction are still thin. Anchors the narrative in market change, founder insight, and credible early signal \u2014 not metrics yet.",audienceFit:["seed-investors","angels","advisors"],durationRange:{minMinutes:10,maxMinutes:20},tags:["startup","fundraising","seed","pitch"],beats:[{id:"logo",name:"Logo",description:"Cover slide with the company name, logo, and one-line positioning. Simple, branded, confident.",layoutHint:"title-left",instructions:"Establish presence",slideType:"text"},{id:"monumental-change",name:"Monumental Change",description:"Open by naming a large, undeniable shift in the world. Tech, regulatory, behavioral. The shift is the reason this company exists \u2014 investors should feel its weight before they hear about the product.",instructions:"Highlight market transformation",slideType:"text",layoutHint:"text-1x-left"},{id:"past-struggle",name:"Past Struggle",description:"Show what the world tried to do about the problem before the shift, and why those approaches fell short. Honest credit to predecessors makes the new game more credible.",instructions:"Emphasize previous challenges",slideType:"text",layoutHint:"text-1x-left"},{id:"innovative-breakthrough",name:"Innovative Breakthrough",description:"Present the founding insight or breakthrough that makes a new approach possible. This is the 'secret' the company is built on \u2014 name it plainly.",instructions:"Present innovative solution",slideType:"text",layoutHint:"text-1x-left"},{id:"unique-offering",name:"Unique Offering",description:"Detail the product or service. Lead with the customer-visible thing they touch; the architecture can wait. Show why this offering is structurally different from the past struggle.",instructions:"Detail product or service",slideType:"text",layoutHint:"text-1x-left"},{id:"costly-issues",name:"Costly Issues",description:"Quantify the pain customers experience without your offering. Time, dollars, opportunity cost. Specific numbers convert sympathy into urgency.",instructions:"Quantify problems faced",slideType:"text",layoutHint:"text-1x-left"},{id:"effective-solutions",name:"Effective Solutions",description:"Demonstrate the customer outcome your offering produces. Before/after numbers from early users, even small N. Early-stage pitches are won by leading indicators, not by trailing ones.",instructions:"Demonstrate benefits",slideType:"text",layoutHint:"text-1x-left"},{id:"unit-economics",name:"Unit Economics",description:"Explain the financial model. Cost to acquire, gross margin, payback. Investors don't expect maturity \u2014 they expect that you've thought about it.",instructions:"Explain financial model",slideType:"text",layoutHint:"text-1x-left"},{id:"talented-team",name:"Talented Team",description:"Introduce the founders and key early hires. Show why this team uniquely sees and can execute on this opportunity. Insight beats r\xE9sum\xE9 at the seed stage.",instructions:"Introduce key players",slideType:"text",layoutHint:"text-1x-left"},{id:"traction",name:"Traction",description:"Showcase the early signal: pilots, design partners, waitlist, retention data, anything credible. Frame it honestly \u2014 investors at this stage discount inflation aggressively.",instructions:"Showcase accomplishments",slideType:"text",layoutHint:"text-1x-left"},{id:"investment-opportunity",name:"Investment Opportunity",description:"Detail the round size, structure, and use of funds. Tie the raise to specific milestones it takes the company to. Specificity here signals operational maturity.",instructions:"Detail funding needs",slideType:"text",layoutHint:"text-1x-left"},{id:"closing-logo",name:"Closing Logo",description:"Close on the brand and contact info. Leave the room with the line you most want repeated when the partner pitches you to the rest of the firm.",layoutHint:"title-left",instructions:"Leave a lasting impression",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"venture-pitch",name:"Venture Pitch",summary:"Series A/B fundraising arc structured around the canonical investor questions.",audienceFit:["investors","venture-capitalists","series-a","series-b"],durationRange:{minMinutes:10,maxMinutes:30},tags:["startup","fundraising","pitch","investor","series-a"],beats:[{id:"opening",name:"Opening",instructions:"Establish identity",slideType:"text",layoutHint:"text-1x-left"},{id:"purpose",name:"Purpose",instructions:"State your mission",slideType:"text",layoutHint:"text-1x-left"},{id:"problem",name:"Problem",instructions:"Present the challenge",slideType:"text",layoutHint:"text-1x-left"},{id:"solution",name:"Solution",instructions:"Propose your idea",slideType:"text",layoutHint:"text-1x-left"},{id:"why-now",name:"Why Now",instructions:"Explain timing importance",slideType:"text",layoutHint:"text-1x-left"},{id:"market-size",name:"Market Size",instructions:"Demonstrate potential",slideType:"text",layoutHint:"text-1x-left"},{id:"competition",name:"Competition",instructions:"Analyze competitive landscape",slideType:"text",layoutHint:"text-1x-left"},{id:"product",name:"Product",instructions:"Showcase features/benefits",slideType:"text",layoutHint:"text-1x-left"},{id:"business-model",name:"Business Model",instructions:"Detail revenue streams",slideType:"text",layoutHint:"text-1x-left"},{id:"team",name:"Team",instructions:"Highlight key members",slideType:"text",layoutHint:"text-1x-left"},{id:"financials",name:"Financials",instructions:"Show projections/needs",slideType:"text",layoutHint:"text-1x-left"},{id:"closing",name:"Closing",instructions:"Reinforce brand",slideType:"text",layoutHint:"text-1x-left"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"persuasive-sales",name:"Persuasive Sales",summary:"Top-of-funnel sales arc that creates awareness and alignment with a prospective customer. Anchored in a market change, leading to your unique capabilities, supported by proof, ending with a clear call to action.",audienceFit:["prospects","customers","buyers"],durationRange:{minMinutes:15,maxMinutes:45},tags:["sales","go-to-market","outbound","discovery"],beats:[{id:"intro",name:"Introduction",description:"Open with a brief framing of who you are and why this conversation is worth the prospect's next thirty minutes. Keep credentials short; the audience cares about their problem, not your r\xE9sum\xE9.",instructions:"Name & logo",slideType:"text",layoutHint:"text-1x-left"},{id:"big-change",name:"Big Change",description:"Name the market shift the prospect's industry is living through. Make it concrete, recent, and undeniable. The change \u2014 not the product \u2014 is the reason they should care.",instructions:"Highlight market shift",slideType:"text",layoutHint:"text-1x-left"},{id:"response-to-change",name:"Winners and Losers",description:"Show how the change is creating winners and losers in the prospect's space. Use named examples where you can. The goal is for the prospect to wonder which side they'll end up on.",instructions:"Show winners & losers",slideType:"text",layoutHint:"text-1x-left"},{id:"benefits",name:"Benefits",description:"Paint the outcome a winner experiences: a vivid picture of the prospect's life on the other side of the change. Lead with what changes for them, not with what your product does.",instructions:"Describe benefits, paint a vivid picture",slideType:"text",layoutHint:"text-1x-left"},{id:"capabilities",name:"Capabilities",description:"Reveal the unique capabilities that make those outcomes possible. Frame them as the 'magic gifts' the prospect needs to win the new game. Highlight what's structurally different from the alternatives.",instructions:"Present unique features as 'magic gifts' to the customer",slideType:"text",layoutHint:"text-1x-left"},{id:"evidence",name:"Evidence",description:"Share customer testimonials, case studies, and measurable outcomes from organizations like the prospect's. Pick evidence that maps to the benefits you promised, not generic logos.",instructions:"Share testimonials",slideType:"text",layoutHint:"text-1x-left"},{id:"call-to-action",name:"Call to Action",description:"Ask for the next step in the sales process. Be specific: a pilot, a workshop, a follow-on conversation with a named stakeholder. Make the smallest credible commitment that keeps momentum.",layoutHint:"title-left",instructions:"Encourage decision-making",slideType:"text"},{id:"close",name:"Close",description:"Close with a final image and contact path. Leave the prospect with one line about why they're better off acting now than later, and clear instructions for how to engage.",layoutHint:"title-left",instructions:"Logo & contact info",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"company-intro",name:"Company Intro",summary:"Standard company-overview deck: who you are, what's distinctive about you, who you serve, and why they win. Built for first-touch sales meetings, partner intros, and 'about us' decks attached to outbound emails.",audienceFit:["prospects","partners","press","candidates"],durationRange:{minMinutes:10,maxMinutes:30},tags:["overview","go-to-market","marketing","intro"],beats:[{id:"logo",name:"Logo",description:"Cover slide with the logo, tagline, and a single line of positioning. Set the visual tone \u2014 confident, branded, uncluttered.",layoutHint:"title-left",instructions:"Establish brand identity",slideType:"text"},{id:"about",name:"About",description:"Capture the company in three or four lines: what you do, who you do it for, and how long you've been at it. Avoid jargon; an outsider should grok the business in fifteen seconds.",instructions:"Capture attention",slideType:"text",layoutHint:"text-1x-left"},{id:"competitive-advantage",name:"Competitive Advantage",description:"State the one or two things you do that the alternatives can't. Frame it as a structural advantage, not a feature list. The audience should leave able to repeat the differentiator in their own words.",instructions:"Stand out",slideType:"text",layoutHint:"text-1x-left"},{id:"company-story",name:"Company Story",description:"Share the founding insight or origin moment \u2014 why this company exists, told as a short story. Specific people, specific problems, a specific 'aha.' Story beats biography.",instructions:"Share origin",slideType:"text",layoutHint:"text-1x-left"},{id:"offerings",name:"Offerings",description:"Map the products and services into a coherent picture. Show how they fit together rather than listing them flat. The shape of the portfolio is itself a message.",instructions:"Highlight products/services",slideType:"text",layoutHint:"text-1x-left"},{id:"ideal-customer",name:"Ideal Customer",description:"Define who you serve best. Industry, size, role, situation. Specificity here helps the audience self-select and signals you understand the customer well enough to be choosy.",instructions:"Define target market",slideType:"text",layoutHint:"text-1x-left"},{id:"key-benefits",name:"Key Benefits",description:"Translate offerings into three to five customer outcomes. Lead with the result, not the mechanism. Each benefit should answer 'what becomes easier or better for me?'",instructions:"Emphasize value",slideType:"text",layoutHint:"text-1x-left"},{id:"success-story",name:"Success Story",description:"Tell one named customer's story with concrete before/after metrics. A single specific story is more persuasive than a logo grid; pick one that mirrors the audience you're presenting to.",instructions:"Showcase satisfied customer",slideType:"text",layoutHint:"text-1x-left"},{id:"closing-cta",name:"Closing & CTA",description:"Close with one line of why now and one specific next step \u2014 a discovery call, a pilot, a partner program. End with contact info that's easy to act on without searching.",layoutHint:"title-left",instructions:"Encourage action",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"marketing-strategy",name:"Marketing Strategy",summary:"Comprehensive go-to-market strategy arc structured around the 4Ps. Use for category launches, annual marketing plans, and any deck where the audience needs to see customer, market, competition, and tactics in one coherent picture.",audienceFit:["marketing-leaders","executives","cross-functional-partners"],durationRange:{minMinutes:30,maxMinutes:60},tags:["go-to-market","marketing","strategy","planning"],beats:[{id:"introduction",name:"Introduction",description:"Open by establishing the product or service this strategy is for, and what window of time it covers. One slide that tells the audience exactly which world they're being asked to weigh in on.",instructions:"Establish product/service specifics",slideType:"text",layoutHint:"text-1x-left"},{id:"objective",name:"Objective",description:"State the marketing goals in measurable terms: revenue, pipeline, awareness, share. Two or three goals, ranked. Goals without ranking get equal energy and equal mediocrity.",instructions:"Share marketing goals",slideType:"text",layoutHint:"text-1x-left"},{id:"customer",name:"Customer",description:"Detail the target audience. Segments, jobs-to-be-done, decision criteria, where they live in the buying cycle. Specificity here is the foundation everything else stands on.",instructions:"Detail target audience",slideType:"text",layoutHint:"text-1x-left"},{id:"market",name:"Market",description:"Describe the market landscape: size, growth, segments, behavioral trends. Use external data for credibility and your own research for nuance. Show how the market is changing, not just how big it is.",instructions:"Discuss market landscape",slideType:"text",layoutHint:"text-1x-left"},{id:"competition",name:"Competition",description:"Map the competitive set honestly. Direct, indirect, and substitutes. A 2x2 or feature-comparison framework helps; what matters is that the audience trusts your read of the field.",instructions:"Analyze competitive environment",slideType:"text",layoutHint:"text-1x-left"},{id:"strategy",name:"Strategy",description:"Articulate the marketing approach in one sentence and a single supporting frame. Positioning, primary motion, where you choose to play and not play. Clarity here is what makes the tactics that follow coherent.",instructions:"Elaborate marketing approach",slideType:"text",layoutHint:"text-1x-left"},{id:"product",name:"Product",description:"Highlight the unique value the product brings to the strategy. Lead with the customer outcome; tie it directly back to the customer beat. Avoid feature soup.",instructions:"Highlight unique value",slideType:"text",layoutHint:"text-1x-left"},{id:"price",name:"Price",description:"Justify pricing and packaging. Show the logic \u2014 cost-plus, value-based, competitor-anchored \u2014 and the levers you'll use over the period. Price decisions are strategy decisions.",instructions:"Justify pricing strategy",slideType:"text",layoutHint:"text-1x-left"},{id:"place",name:"Place",description:"Describe distribution channels and the role each plays. Direct, partner, marketplace, retail. Channel mix is often where strategies quietly succeed or fail.",instructions:"Discuss distribution channels",slideType:"text",layoutHint:"text-1x-left"},{id:"promotion",name:"Promotion",description:"Reveal the campaign and content tactics that bring the strategy to market. Pair each tactic with the audience and metric it serves. Avoid listing channels for their own sake.",instructions:"Reveal promotional tactics",slideType:"text",layoutHint:"text-1x-left"},{id:"summary",name:"Summary",description:"Recap the strategy in a single page: customer, position, motion, expected outcome. End with the decision or commitment you need from the audience.",layoutHint:"title-left",instructions:"Recap key points",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"product-launch",name:"Product Launch",summary:"Persuasive launch arc: open with brand, hook with a promise, set the conflict, raise the stakes, reveal the product, raise stakes again, sell, and call to action. Tuned for keynote-style launches and major announcement decks.",audienceFit:["customers","press","general-audience","partners"],durationRange:{minMinutes:15,maxMinutes:45},tags:["startup","launch","marketing","keynote"],beats:[{id:"opening",name:"Opening",description:"Open with the company brand and a confident visual. Set the tone \u2014 this is a moment, not a meeting. One slide that signals the audience is somewhere worth being.",layoutHint:"title-left",instructions:"Show company branding",slideType:"text"},{id:"promise",name:"Promise",description:"Hook the audience with the promise of the talk. Tell them, in one sentence, what they're about to see and why it matters to them. Specific promises buy patient audiences.",instructions:"Hook the audience",slideType:"text",layoutHint:"text-1x-left"},{id:"context",name:"Context",description:"Set the stage with the world the product enters. The customer reality, the market state, the unmet expectation. Context turns the launch from a product release into a moment in a larger story.",instructions:"Set the stage",slideType:"text",layoutHint:"text-1x-left"},{id:"conflict",name:"Conflict",description:"Introduce the villain \u2014 the problem, friction, or status quo the product opposes. Make the conflict concrete enough that the audience can name a moment they've felt it themselves.",instructions:"Introduce villain/problem",slideType:"text",layoutHint:"text-1x-left"},{id:"stakes",name:"Stakes",description:"Emphasize what's at risk if the conflict isn't resolved. Quantify, personalize, dramatize. Stakes are what convert a curious audience into an invested one.",instructions:"Emphasize importance",slideType:"text",layoutHint:"text-1x-left"},{id:"reveal",name:"Reveal",description:"Showcase the product. One striking visual, one defining capability, one sentence that captures what's new. Earn the applause line; don't bury it under a bullet list.",instructions:"Showcase the solution",slideType:"text",layoutHint:"text-1x-left"},{id:"raise-stakes",name:"Raise the Stakes",description:"Highlight where the alternatives fall short and what they cost the customer. Re-energize the room midway by sharpening the contrast with the reveal.",instructions:"Highlight shortcomings of alternatives",slideType:"text",layoutHint:"text-1x-left"},{id:"raise-stakes-again",name:"Reinforce the Need",description:"Reinforce why change is non-negotiable now. A second beat of stakes, framed differently \u2014 perhaps a customer voice or a future cost. Cement the reason to act.",instructions:"Reinforce the need for change",slideType:"text",layoutHint:"text-1x-left"},{id:"sell",name:"Sell",description:"Make the audience want the product. Lead with the outcome it produces in their lives. Pricing, packaging, availability go here, but only after the desire is built.",instructions:"Make them want your solution",slideType:"text",layoutHint:"text-1x-left"},{id:"cta",name:"Call to Action",description:"Close with the single action you want from the audience. Pre-order, sign up, attend, share. Make it simple, specific, and immediate.",layoutHint:"title-left",instructions:"Inspire action",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"strategic-advisory",name:"Strategic Advisory",summary:"Consulting-style advisory deck applying Minto's pyramid: title, situation/complication/question, the answer in one sentence, and three argued points with a process. Use when the audience expects a recommendation and the case for it, in that order.",audienceFit:["executives","boards","leadership-teams","clients"],durationRange:{minMinutes:15,maxMinutes:45},tags:["consulting","advisory","strategy","minto"],beats:[{id:"title",name:"Title",description:"Open with a one-line summary statement that captures the recommendation, not the topic. The title slide is the headline of the entire engagement \u2014 make it specific enough that someone reading only this slide already understands the position.",layoutHint:"title-left",instructions:"Brief summary sentence",slideType:"text"},{id:"scq",name:"Situation, Complication, Question",description:"Frame the engagement on a single slide: the relevant status quo, what needs to change, and the question that needs to be resolved. This is the SCQ shorthand \u2014 context, tension, prompt. Don't yet answer."},{id:"answer",name:"Answer",description:"Deliver the recommendation in a single sentence. No arguments yet, no caveats. The answer is the apex of the pyramid; the rest of the deck supports it.",instructions:"A solution in one sentence, no arguments yet",slideType:"text",layoutHint:"text-1x-left"},{id:"arguments",name:"Arguments",description:"Preview the three top-level arguments that defend the answer. One slide naming all three so the audience knows where the deck is going. Each argument should be a complete claim, not a topic.",instructions:"Support the solution",slideType:"text",layoutHint:"text-1x-left"},{id:"argument-1",name:"Argument 1",description:"Develop the first argument with supporting data, examples, and reasoning. Lead with the claim, then the evidence \u2014 Minto-style. The slide should stand alone if pulled out.",instructions:"First key point",slideType:"text",layoutHint:"text-1x-left"},{id:"argument-2",name:"Argument 2",description:"Develop the second argument the same way. Vary the type of evidence \u2014 quantitative, qualitative, comparative \u2014 so the audience hears the case from multiple angles.",instructions:"Second key point",slideType:"text",layoutHint:"text-1x-left"},{id:"argument-3",name:"Argument 3",description:"Develop the third argument and walk through the supporting process or methodology. This is often where the 'how' lives \u2014 the implementation insight that makes the recommendation feel actionable.",instructions:"Third key point with a process",slideType:"text",layoutHint:"text-1x-left"},{id:"summary",name:"Summary",description:"Recap the answer and arguments in a single slide and point to additional resources. Close with the explicit next step you want the audience to take.",layoutHint:"title-left",instructions:"Recap the answer, provide additional resources",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"challenge-resolution",name:"Challenge \u2192 Resolution",summary:"Identify a current business challenge, trace its origins, and recommend an actionable resolution. Useful for management consulting, internal strategy memos, and any deck where the audience needs a clear path from problem to plan.",audienceFit:["executives","managers","stakeholders","internal-teams"],durationRange:{minMinutes:10,maxMinutes:30},tags:["management","strategy","consulting","advisory"],beats:[{id:"hook",name:"Hook",description:"Open with a specific, visible signal of the challenge \u2014 a metric heading the wrong way, a customer story, a competitive event. The hook should make the audience nod that yes, this matters.",instructions:"Capture audience attention",slideType:"text",layoutHint:"text-1x-left"},{id:"dilemma",name:"Dilemma",description:"State the challenge plainly. What is failing, who is feeling it, and why has it now risen to a level that demands a decision? The dilemma must feel real, not academic.",instructions:"Present the problem",slideType:"text",layoutHint:"text-1x-left"},{id:"backdrop",name:"Backdrop",description:"Provide the context behind the dilemma: how it formed, what's been tried, what constraints exist. Just enough history that the audience trusts your diagnosis without drowning in detail.",instructions:"Provide context",slideType:"text",layoutHint:"text-1x-left"},{id:"remedy",name:"Remedy",description:"Propose the resolution. Lead with the recommendation, then sketch the approach. Be opinionated \u2014 vague remedies invite vague responses.",instructions:"Propose a solution",slideType:"text",layoutHint:"text-1x-left"},{id:"evidence",name:"Evidence",description:"Demonstrate why the remedy will work. Comparable cases, supporting data, or pilot results. Choose evidence that addresses the audience's most likely objection, not the one easiest to answer.",instructions:"Demonstrate success",slideType:"text",layoutHint:"text-1x-left"},{id:"motivate",name:"Motivate",description:"Make the case for acting now. Quantify the cost of delay and the upside of decisive action. Help the audience picture the room a quarter from now if they say yes.",instructions:"Encourage action",slideType:"text",layoutHint:"text-1x-left"},{id:"conclusion",name:"Conclusion",description:"Recap the challenge, the remedy, and the specific decision you need from the audience. End with a clear ask, not a summary slide.",layoutHint:"title-left",instructions:"Recap and end powerfully",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"project-proposal",name:"Project Proposal",summary:"Internal proposal arc for greenlighting a project: hook, problem, idea, benefits, justification, plan, timeline, risks, outlook, ask. Designed to take a sponsor from 'never heard of this' to 'approved' inside a single meeting.",audienceFit:["executives","sponsors","managers","internal-teams"],durationRange:{minMinutes:15,maxMinutes:45},tags:["management","proposal","internal","planning"],beats:[{id:"elevator-pitch",name:"Elevator Pitch",description:"Open with the proposal in one slide: the project name, the audience, the goal, and the headline benefit. If a sponsor reads only this slide, they should still know what they're being asked to approve.",instructions:"Audience hook & objectives",slideType:"text",layoutHint:"text-1x-left"},{id:"problem-statement",name:"Problem Statement",description:"Articulate the problem this project solves and why it deserves resources now. Tie it to a known business goal or pain. Vague problems produce vague approvals.",instructions:"Highlight struggles & project necessity",slideType:"text",layoutHint:"text-1x-left"},{id:"core-concept",name:"Core Concept",description:"Describe the central idea of the project in plain language. The 'what' before the 'how.' A reader should be able to repeat the concept in one sentence after this slide.",instructions:"Share actionable idea",slideType:"text",layoutHint:"text-1x-left"},{id:"benefits",name:"Benefits",description:"Quantify the impact: revenue, cost, risk, customer, capability. Use numbers where possible and clear comparisons where not. Each benefit should map to a metric the sponsor cares about.",instructions:"Spotlight key metrics",slideType:"text",layoutHint:"text-1x-left"},{id:"justification",name:"Justification",description:"Connect the project to broader strategy, OKRs, or constraints the audience already cares about. Show why this project is more important than the alternatives competing for the same resources.",instructions:"Strategic alignment & significance",slideType:"text",layoutHint:"text-1x-left"},{id:"approach",name:"Approach",description:"Lay out how the project will be executed: the solution, the team shape, the budget envelope. Enough detail to feel credible, not so much that it pre-commits to choices that will mature in flight.",instructions:"Solution, resources, & budget",slideType:"text",layoutHint:"text-1x-left"},{id:"timeline",name:"Timeline",description:"Show the project phases on a timeline, with major milestones and decision points marked. Sponsors are buying a sequence of bets, not a single launch \u2014 make those bets visible.",instructions:"Outline project phases",slideType:"text",layoutHint:"text-1x-left"},{id:"risks",name:"Risks",description:"Name the top risks honestly and pair each with a mitigation or open question. Listing risks without mitigations signals you haven't thought it through; hiding risks signals worse.",instructions:"Consider potential challenges",slideType:"text",layoutHint:"text-1x-left"},{id:"outlook",name:"Outlook",description:"Paint the picture of what the organization looks like a quarter or year after the project ships. Stretch beyond the immediate deliverable to the second-order benefits.",instructions:"Envision project impact",slideType:"text",layoutHint:"text-1x-left"},{id:"wrap-up",name:"Wrap Up",description:"Recap the proposal and state the specific decision you're asking for: approval, budget, headcount, sponsorship. Make it easy to say yes today.",layoutHint:"title-left",instructions:"Summarize & persuade",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"failure-analysis",name:"Failure Analysis",summary:"Walk through what went wrong, why, and what changes \u2014 a structured post-mortem for stakeholder reviews. Pairs honest accountability with a credible recovery plan.",audienceFit:["leadership","customers","stakeholders","partners"],durationRange:{minMinutes:15,maxMinutes:45},tags:["postmortem","incident","review","accountability"],beats:[{id:"opening-remark",name:"Opening Remark",description:"Set an empathetic, accountable tone before any analysis. Acknowledge the impact on the people in the room and the customers affected. Authenticity here earns you the credibility you'll need for the rest of the deck.",instructions:"Set an empathetic tone",slideType:"text",layoutHint:"text-1x-left"},{id:"incident-breakdown",name:"Incident Breakdown",description:"Walk through what happened, in time order. Stick to facts: what systems, what users, what timeline. No causal claims yet \u2014 just an accurate, neutral reconstruction the audience can trust.",instructions:"Detail the failure",slideType:"text",layoutHint:"text-1x-left"},{id:"impact-analysis",name:"Impact Analysis",description:"Quantify the damage. Customer-hours lost, revenue at risk, SLA breaches, downstream knock-ons. Be specific and direct; vague impact statements undermine the rest of the post-mortem.",instructions:"Describe failure's effects",slideType:"text",layoutHint:"text-1x-left"},{id:"root-cause",name:"Root Cause",description:"Trace the failure to its underlying cause, not the most visible symptom. Use a 'five whys' or fishbone framing if useful. Distinguish between the proximate trigger and the systemic conditions that allowed it.",instructions:"Analyze underlying reasons",slideType:"text",layoutHint:"text-1x-left"},{id:"proposed-solutions",name:"Proposed Solutions",description:"Present the corrective actions you're taking. Lead with the highest-leverage fix; sequence the rest. For each action, name an owner and a date \u2014 solutions without owners are aspirations.",instructions:"Suggest corrective measures",slideType:"text",layoutHint:"text-1x-left"},{id:"action-plan",name:"Action Plan",description:"Lay out the rollout: what ships when, how it's verified, who signs off. Show that 'fixed' has a definition and a deadline, not just intent.",instructions:"Map out steps",slideType:"text",layoutHint:"text-1x-left"},{id:"evaluate-outcome",name:"Evaluate Outcome",description:"Define the metrics that will tell you the fix worked. Pre/post comparisons, monitoring SLOs, error budgets \u2014 whatever proves the failure mode is closed and not just deferred.",instructions:"Assess corrective actions",slideType:"text",layoutHint:"text-1x-left"},{id:"lessons-learned",name:"Lessons Learned",description:"Distill the broader lessons that outlive this specific incident. What does the team or organization now know that it didn't before? What patterns will you watch for elsewhere?",instructions:"Reflect on failure lessons",slideType:"text",layoutHint:"text-1x-left"},{id:"preventive-measures",name:"Preventive Measures",description:"List the systemic safeguards being added \u2014 process changes, automated checks, on-call procedures, review gates. Show how this category of failure becomes harder to recur, not just this specific instance.",instructions:"List safeguards",slideType:"text",layoutHint:"text-1x-left"},{id:"closing-thoughts",name:"Closing Thoughts",description:"Close with humility and forward momentum. Re-affirm accountability, thank the audience for their patience, and signal confidence in the path forward without overclaiming.",layoutHint:"title-left",instructions:"Empathize, trust, and encourage",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"classic-story",name:"Classic Story",summary:"Movie-style narrative arc applied to any topic: open the scene, introduce the villain, raise the stakes, send in the hero, deliver the plan, and close with hope. A versatile go-to when you need to make information feel like a story.",audienceFit:["general-audience","customers","internal-teams"],durationRange:{minMinutes:5,maxMinutes:30},tags:["storytelling","general","engagement"],beats:[{id:"opening",name:"Opening",description:"Capture attention with a vivid moment, image, or question that sets the world of the story. The audience should immediately know what kind of room they're in. Avoid agendas \u2014 the opening is the first scene, not a preamble.",instructions:"Capture audience attention",slideType:"text",layoutHint:"text-1x-left"},{id:"context",name:"Context",description:"Establish what's normal in this world before anything goes wrong. Just enough background for the audience to feel the stakes when the villain shows up. Keep it tight; backstory is fuel, not the engine.",instructions:"Give background & importance",slideType:"text",layoutHint:"text-1x-left"},{id:"villain",name:"Villain",description:"Introduce the antagonist \u2014 a problem, a competitor, a market force, an inertia. Give it a face and a name where you can. The clearer the villain, the more the audience cares about how the story turns out.",instructions:"Introduce problem",slideType:"text",layoutHint:"text-1x-left"},{id:"despair",name:"Despair",description:"Show what's at risk if the villain wins. Emphasize the human or business cost of inaction. Don't rush past this beat \u2014 the discomfort here is what makes the resolution land.",instructions:"Emphasize negative impact",slideType:"text",layoutHint:"text-1x-left"},{id:"hero",name:"Hero",description:"Reveal the hero of the story. Often this is the audience themselves, your team, or your product. Frame the hero by what they uniquely bring to the fight, not by their r\xE9sum\xE9.",instructions:"Present solution",slideType:"text",layoutHint:"text-1x-left"},{id:"plan",name:"Plan",description:"Walk through how the hero defeats the villain. Concrete, sequential, credible. Generic plans signal weak heroes; specific plans earn belief that the ending you're promising is reachable.",instructions:"Detail implementation",slideType:"text",layoutHint:"text-1x-left"},{id:"closing",name:"Closing",description:"End with the resolution and the lesson. Show what the world looks like after the villain loses, and leave the audience with the feeling \u2014 and the line \u2014 they'll repeat afterwards.",layoutHint:"title-left",instructions:"Inspire & conclude",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"business-narrative",name:"Business Narrative",summary:"Tell a business strategy or solution as a story: setting, challenge, tension, hero, plan, outcome. Useful for internal alignment decks, town halls, and any audience that responds better to story shape than to bullet lists.",audienceFit:["internal-teams","leadership","cross-functional-partners"],durationRange:{minMinutes:10,maxMinutes:30},tags:["management","storytelling","internal","strategy"],beats:[{id:"introduction",name:"Introduction",description:"Engage the audience and set expectations for the next twenty minutes. Tell them you're going to tell them a story \u2014 and then start telling it. Avoid a separate agenda slide; the introduction is the first scene.",instructions:"Engage and set expectations",slideType:"text",layoutHint:"text-1x-left"},{id:"setting",name:"Setting",description:"Establish the world the story takes place in: the team, the market, the moment. Just enough context that the challenge will feel meaningful when it arrives.",instructions:"Establish the environment",slideType:"text",layoutHint:"text-1x-left"},{id:"challenge",name:"Challenge",description:"Identify the issue at hand. Concrete, specific, attributable. The challenge is the inciting incident \u2014 the thing that pulled the rest of the story into motion.",instructions:"Identify the issue at hand",slideType:"text",layoutHint:"text-1x-left"},{id:"tension",name:"Tension",description:"Raise the stakes. What happens if the challenge isn't met? Quantify the cost, name the people affected, surface the trade-offs that make the choice hard. Tension is what makes the audience lean in.",instructions:"Emphasize the stakes",slideType:"text",layoutHint:"text-1x-left"},{id:"solution",name:"Solution",description:"Reveal the strategy or hero of the story. Lead with what changes for the audience or customer when the solution is in place. This is the turn from problem to promise.",instructions:"Present the hero/strategy",slideType:"text",layoutHint:"text-1x-left"},{id:"implementation",name:"Implementation",description:"Describe the path to success. Phases, owners, milestones, key bets. Show the audience that the solution has weight behind it \u2014 not just intent.",instructions:"Describe the path to success",slideType:"text",layoutHint:"text-1x-left"},{id:"recap",name:"Recap",description:"Bring the audience back to the surface with a clear summary of what was said and decided. Echo the language from the opening so the story feels closed.",instructions:"Review key points and insights",slideType:"text",layoutHint:"text-1x-left"},{id:"conclusion",name:"Conclusion",description:"Reinforce the key message and the call to action. End on the line you most want repeated in tomorrow's hallway conversations.",layoutHint:"title-left",instructions:"Reinforce takeaways and call to action",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"rags-to-riches",name:"Rags to Riches",summary:"Underdog journey from initial failure to eventual success. Pulls on resilience, grit, and perseverance \u2014 useful for founder stories, brand stories, and any deck where the audience needs to feel the cost behind the win.",audienceFit:["general-audience","customers","press","candidates"],durationRange:{minMinutes:5,maxMinutes:20},tags:["storytelling","founder","brand","inspirational"],beats:[{id:"origin",name:"Origin",description:"Start at the bottom. Describe the humble beginning, the constraint, the moment before anything had been built. Concrete details \u2014 a place, a year, a feeling \u2014 earn the audience's investment in what follows.",instructions:"Humble beginning",slideType:"text",layoutHint:"text-1x-left"},{id:"inspiration",name:"Inspiration",description:"Show the moment the protagonist found their calling. A conversation, a customer, a problem they couldn't unsee. The inspiration is the engine that pushes the rest of the story uphill.",instructions:"Discover true calling",slideType:"text",layoutHint:"text-1x-left"},{id:"opportunity",name:"Opportunity",description:"Reveal the chance the protagonist took. Why this and not something safer? Make the choice visible \u2014 opportunities only count when there was something else they passed up to grab them.",instructions:"Spot golden chance",slideType:"text",layoutHint:"text-1x-left"},{id:"adversity",name:"Adversity",description:"Walk through the hardest stretch. Concrete failures, near-misses, moments of doubt. Resist the temptation to skip past the pain \u2014 the audience trusts the win more when the loss was real.",instructions:"Face hardest struggles",slideType:"text",layoutHint:"text-1x-left"},{id:"overcoming",name:"Overcoming",description:"Show how the obstacles got beaten. What changed, what was learned, what hard call was made. The transition from 'rags' to 'riches' should feel earned, not granted.",instructions:"Surmount tough obstacles",slideType:"text",layoutHint:"text-1x-left"},{id:"impactful-change",name:"Impactful Change",description:"Describe the moment the world tipped. The customer who said yes, the product that broke through, the metric that turned. One concrete transformation lands harder than a montage.",instructions:"Alter the status quo",slideType:"text",layoutHint:"text-1x-left"},{id:"lasting-legacy",name:"Lasting Legacy",description:"Close on what the journey means for those who come next. The lesson, the people changed, the work that endures. Leave the audience with a takeaway that outlives the story.",layoutHint:"title-left",instructions:"Create enduring effect",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"underdog-victory",name:"Underdog Victory",summary:"Story arc of someone or something overlooked who triumphs in the end. Useful for founder narratives, brand stories, and team-building decks where the lesson is about resilience and unexpected wins.",audienceFit:["general-audience","internal-teams","candidates"],durationRange:{minMinutes:5,maxMinutes:20},tags:["storytelling","inspirational","founder","team"],beats:[{id:"origin",name:"Origin",description:"Establish the opening scene: who the underdog is and the world that overlooked them. Specific details make the rest of the journey feel real.",instructions:"Establish opening scene",slideType:"text",layoutHint:"text-1x-left"},{id:"struggles",name:"Struggles",description:"Highlight the early setbacks. What didn't work, who said no, where the path closed up. The audience needs to feel the doubt before they can feel the win.",instructions:"Highlight initial setbacks",slideType:"text",layoutHint:"text-1x-left"},{id:"determination",name:"Determination",description:"Showcase the enduring passion that kept the underdog going. What they refused to give up on, and why. Determination, in this beat, is the only resource the underdog has.",instructions:"Showcase enduring passion",slideType:"text",layoutHint:"text-1x-left"},{id:"crisis",name:"Crisis",description:"Identify the lowest point of the journey. The moment the dream nearly ended. Don't soften \u2014 the contrast with the triumph ahead depends on the depth of this slide.",instructions:"Identify lowest point",slideType:"text",layoutHint:"text-1x-left"},{id:"resolve",name:"Resolve",description:"Articulate the choice the underdog made to keep going. The strong will, the small bet, the borrowed faith. Resolve is where the protagonist becomes someone the audience roots for.",instructions:"Articulate strong will",slideType:"text",layoutHint:"text-1x-left"},{id:"breakthrough",name:"Breakthrough",description:"Show the reward of perseverance: the customer who said yes, the door that opened, the fortune that turned. The breakthrough should feel earned, not granted.",instructions:"Reward of perseverance",slideType:"text",layoutHint:"text-1x-left"},{id:"triumph",name:"Triumph",description:"Reveal the ultimate success. Concrete outcomes, named milestones. The triumph is the audience's emotional payoff \u2014 let it land.",instructions:"Reveal ultimate success",slideType:"text",layoutHint:"text-1x-left"},{id:"legacy",name:"Legacy",description:"Share the lasting impact. What the underdog's victory makes possible for those who come after. The legacy beat is what turns a story into a lesson.",layoutHint:"title-left",instructions:"Share long-lasting impact",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"survival-story",name:"Survival Story",summary:"Narrative arc of overcoming adversity through determination: catastrophe, backstory, plan, danger, effort, struggle, pivot, breakthrough, legacy, takeaway. For brand stories, founder histories, and leadership talks where the lesson lives in the comeback.",audienceFit:["general-audience","internal-teams","press"],durationRange:{minMinutes:10,maxMinutes:30},tags:["storytelling","inspirational","founder","comeback"],beats:[{id:"catastrophe",name:"Catastrophe",description:"Open in the middle of the disaster. Specific moment, specific stakes, specific damage. Drop the audience into the worst point of the story before walking them back.",instructions:"Present initial disaster",slideType:"text",layoutHint:"text-1x-left"},{id:"backstory",name:"Backstory",description:"Detail the events that led up to the catastrophe. Just enough for the audience to understand how the disaster could have happened. Avoid moralizing \u2014 the story does the work.",instructions:"Detail past events",slideType:"text",layoutHint:"text-1x-left"},{id:"blueprint",name:"Blueprint",description:"Illustrate the recovery plan. Specific moves, specific bets, specific people. The audience should see the strategy as more than 'try hard.'",instructions:"Illustrate recovery plans",slideType:"text",layoutHint:"text-1x-left"},{id:"danger",name:"Danger",description:"Highlight the emerging threats to the recovery plan. New risks, returning ones. Tension here makes the eventual triumph credible.",instructions:"Highlight emerging threats",slideType:"text",layoutHint:"text-1x-left"},{id:"endeavor",name:"Endeavor",description:"Show the determined effort underway. The hours, the trade-offs, the discipline. The audience must feel the work, not just hear about it.",instructions:"Show determination effort",slideType:"text",layoutHint:"text-1x-left"},{id:"struggles",name:"Struggles",description:"Showcase challenging moments along the way: the setbacks, the false starts, the hard calls. Honest setbacks make eventual success feel earned.",instructions:"Showcase challenging encounters",slideType:"text",layoutHint:"text-1x-left"},{id:"pivot",name:"Pivot",description:"Highlight the strategic shift that changed the trajectory. What got reconsidered, what got dropped, what got doubled down on. The pivot is the moment the protagonist became something new.",instructions:"Highlight strategy shift",slideType:"text",layoutHint:"text-1x-left"},{id:"breakthrough",name:"Breakthrough",description:"Emphasize the moment adversity finally broke. Concrete result, concrete date. Let the slide land \u2014 the audience came for this turn.",instructions:"Emphasize overcoming adversity",slideType:"text",layoutHint:"text-1x-left"},{id:"legacy",name:"Legacy",description:"Discuss the enduring impact. What survival made possible afterward, who benefited, what was built on top. Survival stories are most powerful when they create more than they restore.",instructions:"Discuss enduring impact",slideType:"text",layoutHint:"text-1x-left"},{id:"takeaway",name:"Takeaway",description:"Share the lesson the audience can carry away. One transferable insight, framed for their own challenges \u2014 not a general moral.",layoutHint:"title-left",instructions:"Share important lessons",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"educate",name:"Educate",summary:"Engaging-explainer arc inspired by Mary Roach: surprise the audience with a fact, walk them through evidence and anecdote, scrutinize the assumptions, then close on a memorable insight. For technical, scientific, or analytical talks that need to feel more like discovery than instruction.",audienceFit:["general-audience","students","practitioners"],durationRange:{minMinutes:15,maxMinutes:45},tags:["keynote","education","explainer","science"],beats:[{id:"introduction",name:"Introduction",description:"Introduce the topic in a way that respects the audience's time and curiosity. Frame why this question is worth asking, and signal the shape of the journey ahead without giving away the destination.",instructions:"Introduce the topic",slideType:"text",layoutHint:"text-1x-left"},{id:"surprising-fact",name:"Surprising Fact",description:"Lead with a single curious fact that recasts how the audience thinks about the topic. The fact should be small, specific, and unforgettable \u2014 the cognitive door the rest of the talk walks through.",instructions:"Share a curious fact",slideType:"text",layoutHint:"text-1x-left"},{id:"experiment",name:"Experiment",description:"Walk through a method, study, or thought experiment that probes the surprising fact. Show how knowledge here gets made \u2014 the audience should feel like they're shoulder-to-shoulder with the investigator.",instructions:"Explain a tried method",slideType:"text",layoutHint:"text-1x-left"},{id:"amusing-anecdote",name:"Amusing Anecdote",description:"Drop in a story or moment from the field that brings the topic to human scale. Personality and humor here keep the audience leaning forward; technical depth without warmth loses the room.",instructions:"Relay an interesting story",slideType:"text",layoutHint:"text-1x-left"},{id:"intriguing-information",name:"Intriguing Information",description:"Layer in the more complex data or detail. By this point the audience is invested enough to do real work alongside you. Visualize generously \u2014 make the numbers tangible.",instructions:"Share complex data",slideType:"text",layoutHint:"text-1x-left"},{id:"skeptical-scrutiny",name:"Skeptical Scrutiny",description:"Question the easy interpretations. Challenge the audience's defaults and your own. Showing where the evidence is contested is what separates a teacher from a publicist.",instructions:"Encourage questioning of accepted truths",slideType:"text",layoutHint:"text-1x-left"},{id:"extraordinary-explanation",name:"Extraordinary Explanation",description:"Present the most counterintuitive or beautiful explanation the topic offers. Take your time here \u2014 this is the payoff slide the audience came for.",instructions:"Break down unusual research findings",slideType:"text",layoutHint:"text-1x-left"},{id:"unconventional-use",name:"Unconventional Use",description:"Show an unexpected application or implication of the idea. Surprise reinforces the lesson and gives the audience a story to retell tomorrow.",instructions:"Expand on unique aspects",slideType:"text",layoutHint:"text-1x-left"},{id:"captivating-conclusion",name:"Captivating Conclusion",description:"Close with a thoughtful, slightly poetic wrap-up. Echo the surprising fact, name the lesson, and leave the audience with a new question instead of a tidy answer.",layoutHint:"title-left",instructions:"Provide a thoughtful wrap-up",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"persuade",name:"Persuade",summary:"Argument-driven keynote arc inspired by Ken Robinson: grip the audience, challenge the status quo, define the problem, anchor it in story and statistic, deliver a major revelation, propose change, and end on a question that stays with them.",audienceFit:["general-audience","policymakers","industry-peers"],durationRange:{minMinutes:15,maxMinutes:30},tags:["keynote","persuasive","advocacy","talk"],beats:[{id:"gripping-introduction",name:"Gripping Introduction",description:"Open with a moment, image, or claim the audience can't easily look away from. The first sixty seconds buy you the next twenty minutes \u2014 spend them on something specific and emotionally charged, not on housekeeping.",instructions:"Draw in the audience with a compelling opener",slideType:"text",layoutHint:"text-1x-left"},{id:"challenge-status-quo",name:"Challenge the Status Quo",description:"Call out the system, norm, or assumption that needs examination. Be precise about what you're disagreeing with so the rest of the talk can be specific in response. Avoid strawmen \u2014 name the strongest version of the view you're contesting."},{id:"present-problem",name:"Present the Problem",description:"Define the issue the audience needs to care about. Concrete, scoped, attributable. The clearer the problem, the more credible the eventual solution."},{id:"personal-story",name:"Personal Story",description:"Anchor the issue in a specific person, place, or moment. Story is what gets the argument past the audience's defenses. Pick a story that personalizes the data without overstating it.",instructions:"Share significant stories to illuminate the issue",slideType:"text",layoutHint:"text-1x-left"},{id:"statistic-shock",name:"Statistic Shock",description:"Drop in a single statistic that recasts the scale of the problem. One number, presented well, lands harder than a dashboard. Cite the source so the audience can repeat it with confidence.",instructions:"Use impactful stats to highlight the gravity of the issue",slideType:"text",layoutHint:"text-1x-left"},{id:"historical-context",name:"Historical Context",description:"Show how the issue evolved. Why it has the shape it does today, what was tried, what was missed. Historical context turns 'this is broken' into 'this stayed broken for these reasons.'",instructions:"Show the evolution or history of the issue",slideType:"text",layoutHint:"text-1x-left"},{id:"weave-narrative",name:"Weave a Narrative",description:"Connect the threads \u2014 story, statistic, history \u2014 into a single argument. The audience should feel the case clicking together. This is the slide where rhetoric becomes architecture."},{id:"major-revelation",name:"Major Revelation",description:"Deliver the surprising or significant turn. The fact, finding, or reframing the rest of the talk has been earning. The revelation should redirect, not merely confirm.",instructions:"Deliver a surprising or significant discovery",slideType:"text",layoutHint:"text-1x-left"},{id:"propose-solution",name:"Propose Solution",description:"Advocate for the change you want. Concrete enough to be acted on, broad enough to inspire. Pair the solution with the smallest credible first step.",instructions:"Advocate for change or propose an actionable solution",slideType:"text",layoutHint:"text-1x-left"},{id:"final-question",name:"Final Question",description:"Close on a question rather than a summary. The right closing question follows the audience out of the room and into their conversations afterward.",layoutHint:"title-left",instructions:"Finish with a thought-provoking question to stimulate audience thinking",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"reveal",name:"Reveal",summary:"Insight-driven keynote arc inspired by Amy Cuddy's 2012 talk on body language: connect through personal story, ground in research, illustrate with anecdote, summarize, break stereotypes, advise, demonstrate authenticity, close with impact. For talks that aim to change how the audience sees something they thought they understood.",audienceFit:["general-audience","academics","professionals"],durationRange:{minMinutes:15,maxMinutes:25},tags:["keynote","research","talk","inspirational"],beats:[{id:"personal-story",name:"Personal Story",description:"Open with a personal experience that establishes why the topic matters to you. Specificity earns intimacy; intimacy earns the audience's permission to be moved.",instructions:"Share personal experiences to connect with the audience",slideType:"text",layoutHint:"text-1x-left"},{id:"research-exposition",name:"Research Exposition",description:"Lay out the scientific or empirical data that backs the premise. Be rigorous but not academic \u2014 the audience needs to understand the evidence well enough to defend it later.",instructions:"Unravel scientific data backing the premise",slideType:"text",layoutHint:"text-1x-left"},{id:"real-life-anecdote",name:"Real-Life Anecdote",description:"Illustrate the research with a story from the field. Make the abstract finding feel like something that happens to people the audience could imagine being.",instructions:"Illustrate with stories to make the point relatable",slideType:"text",layoutHint:"text-1x-left"},{id:"critical-insights",name:"Critical Insights",description:"Summarize the two or three findings the audience must walk away with. Distill them into language a non-specialist could repeat without distortion.",instructions:"Summarize key points",slideType:"text",layoutHint:"text-1x-left"},{id:"break-stereotypes",name:"Break Stereotypes",description:"Question redundant norms or beliefs the research undermines. Be specific about what's being challenged so the audience knows what to update.",instructions:"Question redundant norms and belief systems",slideType:"text",layoutHint:"text-1x-left"},{id:"empowering-advice",name:"Empowering Advice",description:"Translate the insights into a small, actionable practice. The advice should be doable today, not only next quarter \u2014 the goal is movement, not aspiration.",instructions:"Motivational message to act upon",slideType:"text",layoutHint:"text-1x-left"},{id:"authenticity",name:"Authenticity",description:"Speak honestly about your own struggle with the topic. Vulnerability, used with restraint, is what turns research into a felt truth.",instructions:"Honest and real communication to demonstrate authenticity",slideType:"text",layoutHint:"text-1x-left"},{id:"close-with-impact",name:"Close With Impact",description:"End on a motivational high \u2014 the line, image, or invitation you want to follow the audience out of the room. Close the talk where it began, transformed.",layoutHint:"title-left",instructions:"End on a motivational high",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"justice",name:"Justice",summary:"Advocacy arc inspired by the rhetorical structure of Martin Luther King Jr.'s 'I Have a Dream' speech: name the inequality, share the dream, build urgency, layer further visions, emphasize unity, call to action, and close on hope. For movement-building keynotes and mission-driven speeches.",audienceFit:["general-audience","advocates","policymakers","community"],durationRange:{minMinutes:10,maxMinutes:30},tags:["inspirational","advocacy","movement","keynote"],beats:[{id:"introduction",name:"Introduction",description:"Set the stage with a moment that earns the audience's full attention. Speak in the moral register the rest of the talk will require. Avoid throat-clearing \u2014 open as if the speech were already underway.",instructions:"Set the stage",slideType:"text",layoutHint:"text-1x-left"},{id:"give-context",name:"Give Context",description:"Place the issue in its historical and current context. What promises were made, what has and hasn't been kept. Context turns the speech from opinion into accountability.",instructions:"Put in historical and current context",slideType:"text",layoutHint:"text-1x-left"},{id:"highlight-inequality",name:"Highlight Inequality",description:"Show specific, undeniable examples of the inequality at issue. Concrete moments and people, not abstractions. The audience should feel the gap between what is and what was promised.",instructions:"Show examples of inequality",slideType:"text",layoutHint:"text-1x-left"},{id:"share-dream",name:"Share the Dream",description:"Describe the future you envision in vivid, specific detail. The dream must be both ambitious and recognizable \u2014 a world the audience can picture themselves living in.",instructions:"Describe your vision",slideType:"text",layoutHint:"text-1x-left"},{id:"create-urgency",name:"Create Urgency",description:"Explain why the time for change is now. The cost of waiting, the moment that won't return. Urgency converts shared vision into shared movement.",instructions:"Explain the need for immediate change",slideType:"text",layoutHint:"text-1x-left"},{id:"another-dream",name:"Continue the Vision",description:"Layer additional visions of the future in parallel structure. Repetition and rhythm build momentum the way a single image cannot.",instructions:"Continue to elaborate on your vision",slideType:"text",layoutHint:"text-1x-left"},{id:"emphasize-unity",name:"Emphasize Unity",description:"Speak to the collective power of the audience together. Name common ground that crosses lines the issue normally divides. Unity is the engine that turns dream into march.",instructions:"Talk about collective power",slideType:"text",layoutHint:"text-1x-left"},{id:"last-dream",name:"Final Vision",description:"Deliver one more, fully realized vision of the world you're calling for. Specific enough to be remembered, expansive enough to inspire.",instructions:"Further share dreams of ideal in-depth",slideType:"text",layoutHint:"text-1x-left"},{id:"call-to-action",name:"Call to Action",description:"Ask the audience to participate in the change. Be specific about what 'doing something' looks like \u2014 show, march, give, vote, organize. Vague CTAs produce vague action.",instructions:"Ask audience to participate in change",slideType:"text",layoutHint:"text-1x-left"},{id:"show-determination",name:"Show Determination",description:"Encourage persistence in the face of resistance. Acknowledge what will be hard. Determination, named honestly, is more durable than easy optimism.",instructions:"Encourage persistence",slideType:"text",layoutHint:"text-1x-left"},{id:"create-hope",name:"Create Hope",description:"Close on hope grounded in evidence: progress already made, victories already won, ground already moved. Hope as a conclusion lands strongest when it sounds like it has been earned.",layoutHint:"title-left",instructions:"Inspire hope for future",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"innovation",name:"Innovation",summary:"Keynote-style product reveal inspired by Steve Jobs's 2007 iPhone launch: stage-set, reveal, demonstrate, wow, differentiate, reframe the category, build excitement, call to action, and thank the audience. For category-defining product moments.",audienceFit:["customers","press","developers","general-audience"],durationRange:{minMinutes:20,maxMinutes:60},tags:["inspirational","keynote","launch","product"],beats:[{id:"opening",name:"Opening",description:"Set the stage. Tell the audience they're about to see something that matters, without yet showing it. The pause before the reveal is part of the reveal.",layoutHint:"title-left",instructions:"Set the stage",slideType:"text"},{id:"revelation",name:"Revelation",description:"Announce the product. One image, one name, one sentence. Anything more competes with the moment. The slide should feel like the curtain going up.",instructions:"Announce product",slideType:"text",layoutHint:"text-1x-left"},{id:"demonstration",name:"Demonstration",description:"Show the product in real use. Choose a single defining workflow that captures what the product does and how it feels. Live beats canned wherever possible.",instructions:"Showcase the product",slideType:"text",layoutHint:"text-1x-left"},{id:"wow-factor",name:"Wow Factor",description:"Highlight the cutting-edge feature that earns the headline. One thing, presented well \u2014 the audience should leave able to repeat it in a sentence.",instructions:"Highlight cutting-edge features",slideType:"text",layoutHint:"text-1x-left"},{id:"differentiation",name:"Differentiation",description:"Make the contrast with existing alternatives unmistakable. Use comparisons that the audience already understands; don't argue against straw versions of the competition.",instructions:"Distinctive factors",slideType:"text",layoutHint:"text-1x-left"},{id:"revolution",name:"Revolution",description:"Reframe the category. Show how the product changes what the playing field looks like, not just where you sit on it. This is the slide pundits will quote.",instructions:"Change in the playing field",slideType:"text",layoutHint:"text-1x-left"},{id:"excitement",name:"Excitement",description:"Build anticipation around what's next: availability, partnerships, what the audience can imagine doing with the product. Excitement is how the room exits the keynote into the world.",instructions:"Build anticipation",slideType:"text",layoutHint:"text-1x-left"},{id:"call-to-action",name:"Call to Action",description:"Give the audience the action that channels the excitement. Pre-order, try it, tell others. Be specific so the energy converts into behavior.",instructions:"Urge to explore",slideType:"text",layoutHint:"text-1x-left"},{id:"gratitude",name:"Gratitude",description:"Thank the team that built it and the audience that came. Brief, sincere, not perfunctory. The closing thanks is the period at the end of the keynote.",layoutHint:"title-left",instructions:"Thank the audience",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"focus",name:"Focus",summary:"Long-term, principle-driven business arc inspired by Jeff Bezos's 1997 letter to shareholders: name the focus, account for performance, articulate the framework, and commit to the discipline that will keep the company on track. For founder letters, all-hands narratives, and any deck where the audience needs to feel the through-line.",audienceFit:["shareholders","leadership","all-hands","board"],durationRange:{minMinutes:20,maxMinutes:45},tags:["inspirational","leadership","principles","all-hands"],beats:[{id:"welcome",name:"Welcome",description:"Open with a brief framing of what this update is for and what you intend to leave the audience with. Set the tone \u2014 long-term, candid, principle-driven.",instructions:"Overview and objectives",slideType:"text",layoutHint:"text-1x-left"},{id:"accomplishments",name:"Accomplishments",description:"Showcase the period's most material wins, briefly. The audience came for what's next; wins earn permission for the harder slides ahead, but they aren't the headline.",instructions:"Showcase recent achievements",slideType:"text",layoutHint:"text-1x-left"},{id:"potential",name:"Potential",description:"Detail the market and customer opportunities ahead. Size them honestly and connect them to the work already underway. Potential without specifics reads as wishful.",instructions:"Detail market opportunities",slideType:"text",layoutHint:"text-1x-left"},{id:"competitive-edge",name:"Competitive Edge",description:"Reveal the strategic positioning that gives the business its advantage. Frame it as a structural moat, not a list of features. The audience should be able to repeat the moat in their own words.",instructions:"Reveal strategic positioning",slideType:"text",layoutHint:"text-1x-left"},{id:"long-term-vision",name:"Long-Term Vision",description:"Emphasize the long-term view that anchors decisions. Quarters serve years; years serve decades. Anchor the audience in the time horizon you actually run the business on.",instructions:"Emphasize focused future orientation",slideType:"text",layoutHint:"text-1x-left"},{id:"performance-metrics",name:"Performance Metrics",description:"Illuminate the indicators that show the long-term thesis is working. Choose metrics that compound \u2014 retention, NPS, unit economics \u2014 over those that flatter.",instructions:"Illuminate growth indicators",slideType:"text",layoutHint:"text-1x-left"},{id:"growth-achievement",name:"Growth Achievement",description:"Certify the tangible progress against the long-term plan. Year-over-year, cohort behavior, expanded reach. Growth, in this beat, is evidence that the strategy is real.",instructions:"Certify tangible progress",slideType:"text",layoutHint:"text-1x-left"},{id:"strategic-framework",name:"Strategic Framework",description:"Explain the principles that guide decisions. Customer obsession, long-term thinking, frugality, ownership \u2014 whatever the actual operating discipline is. Principles are the connective tissue between strategy and behavior.",instructions:"Explain decision principles",slideType:"text",layoutHint:"text-1x-left"},{id:"expansion",name:"Expansion",description:"Detail the next areas of growth: products, segments, geographies. Tie each to the principles above so the audience sees expansion as continuity rather than scatter.",instructions:"Detail growth potential",slideType:"text",layoutHint:"text-1x-left"},{id:"future-objectives",name:"Future Objectives",description:"Forecast the targets and commitments for the period ahead. Be specific enough to be held accountable. Vague objectives are how strategies erode.",instructions:"Forecast upcoming targets",slideType:"text",layoutHint:"text-1x-left"},{id:"acknowledgment",name:"Acknowledgment",description:"Recognize the contributions of teams, customers, and partners that made the period possible. Specific names land harder than blanket thanks.",instructions:"Recognize contributions and successes",slideType:"text",layoutHint:"text-1x-left"},{id:"closing-remarks",name:"Closing Remarks",description:"Recap the focus, thank the audience, and inspire the work ahead. End with the line you most want quoted in tomorrow's newsletter.",layoutHint:"title-left",instructions:"Recap, thank, inspire",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"qbr",name:"Quarterly Business Review",summary:"Standard QBR / business-review arc for internal leadership reviews. Recap commitments, show what the numbers say, separate wins from challenges, lay out the plan, surface risks, and request the asks the team needs to execute.",audienceFit:["leadership","executives","cross-functional-partners"],durationRange:{minMinutes:30,maxMinutes:90},tags:["internal","review","operations","reporting"],beats:[{id:"objectives",name:"Objectives",description:"Open with what this review is for and what decisions you want out of it. Frame the scope and the hour ahead, so the audience knows what they're being asked to weigh in on.",layoutHint:"title-center",instructions:"Set the expectations",slideType:"text"},{id:"recap",name:"Recap",description:"Briefly remind the audience what the team committed to last quarter and the high-level results against those commitments. Keep it terse \u2014 this grounds the review in prior context, but the meat is ahead."},{id:"performance-headline",name:"Performance Headline",description:"Show the top three to five KPIs with target vs actual and direction-of-travel. One slide that lets a busy executive grasp the quarter's outcome at a glance. Lead with the number, not the methodology."},{id:"performance-detail",name:"Performance Detail",description:"Drill into the supporting metrics by area or function. One chart per metric; clear y-axis, clear unit, clear comparison period. Call out anomalies before someone else does."},{id:"wins",name:"Wins",description:"Highlight the quarter's biggest wins and who drove them. Be specific \u2014 name the deal, the launch, the customer, the team. Recognition belongs in the deck, not just in the meeting."},{id:"challenges",name:"Challenges",description:"Name the misses and headwinds honestly. What didn't work, what's still hard, what got harder. Pretending things are fine costs more credibility than acknowledging they aren't.",instructions:"Address difficulties",slideType:"text",layoutHint:"text-1x-left"},{id:"insights",name:"Insights",description:"Translate the numbers into 'so what.' What did the data tell you about customers, the market, your operations, your bets? Insights should be opinions backed by evidence, not restatements of the metrics."},{id:"priorities",name:"Next-Quarter Priorities",description:"Lay out the next quarter's top priorities. Each should trace clearly back to an insight or commitment. Three to five priorities, max \u2014 laundry lists are a tell that the team hasn't decided what matters most."},{id:"sequencing",name:"Sequencing",description:"Show the order in which priorities ship and how they fit together. Dependencies, milestones, target dates. The audience should leave able to predict what comes when, not just what."},{id:"risks",name:"Risks",description:"Name the risks to the plan honestly. Dependencies, assumptions, capacity gaps, market factors. For each risk, state the mitigation or the open question the audience can help resolve."},{id:"asks",name:"Asks",description:"Specific, named requests of the audience. Decisions needed, resources required, escalations to unblock. End with clarity on what happens next and who owns it.",layoutHint:"title-left"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"business-review",name:"Business Review",summary:"Full-loop review of recent activities to identify achievements, address challenges, and plan improvements. Goes deeper than a status update \u2014 closer to a customer-facing or partner-facing relationship review.",audienceFit:["customers","partners","stakeholders","leadership"],durationRange:{minMinutes:30,maxMinutes:90},tags:["customer-relationship","review","operations"],beats:[{id:"logo",name:"Logo",description:"Cover slide with logos and the review period. Establishes brand identity and signals the level of formality the rest of the deck will hold to.",layoutHint:"title-left",instructions:"Identity & representation",slideType:"text"},{id:"opening",name:"Opening",description:"Frame the meeting context and the goals for the next hour. What you'll cover, what decisions you want, what you don't intend to relitigate.",instructions:"Meeting context & goals",slideType:"text",layoutHint:"text-1x-left"},{id:"review",name:"Review",description:"Outline the recent activities in scope: launches, projects, programs. Just enough scope-setting that the rest of the deck has shared vocabulary.",instructions:"Outline recent activities",slideType:"text",layoutHint:"text-1x-left"},{id:"successes",name:"Successes",description:"Recognize the achievements in the review window. Lead with outcomes the audience cares about, not effort. Specific moves earn more credibility than aggregate progress.",instructions:"Recognize achievements",slideType:"text",layoutHint:"text-1x-left"},{id:"challenges",name:"Challenges",description:"Address the problems faced honestly. What didn't work, what's still hard. Naming challenges in front of the audience earns more trust than letting them ask.",instructions:"Address problems faced",slideType:"text",layoutHint:"text-1x-left"},{id:"solutions",name:"Solutions",description:"Discuss the fixes already implemented. Pair each with the result it produced, or, if it's still in flight, with the leading indicator you're watching.",instructions:"Discuss implemented fixes",slideType:"text",layoutHint:"text-1x-left"},{id:"outcome",name:"Outcome",description:"Display the results achieved across the review window. Let the data carry the slide; supporting commentary should explain context, not inflate the numbers.",instructions:"Display results achieved",slideType:"text",layoutHint:"text-1x-left"},{id:"insights",name:"Insights",description:"Highlight the key learnings. What was confirmed, what surprised you, what the audience should take away. Insights are the slides people quote in follow-on meetings.",instructions:"Highlight key learnings",slideType:"text",layoutHint:"text-1x-left"},{id:"future-strategy",name:"Future Strategy",description:"Define the next steps and the strategic direction that follows from the review. Specific enough to sequence; flexible enough to adapt.",instructions:"Define next steps",slideType:"text",layoutHint:"text-1x-left"},{id:"feedback",name:"Feedback",description:"Capture audience thoughts. Two or three explicit prompts where you want input or alignment. The strength of a relationship review is in the conversation it provokes.",instructions:"Capture audience thoughts",slideType:"text",layoutHint:"text-1x-left"},{id:"next-review",name:"Next Review",description:"Plan for follow-up: when the next review happens, what evidence you'll bring, what decisions are deferred until then. Continuity is the point of the cadence.",instructions:"Plan for follow-up",slideType:"text",layoutHint:"text-1x-left"},{id:"closing",name:"Closing",description:"Recap and express optimism about the path forward. Close with the next concrete step and the people responsible for it.",layoutHint:"title-left",instructions:"Recap and express optimism",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"board-meeting",name:"Board Meeting",summary:"Comprehensive board update covering CEO commentary, key metrics, financials, functional updates, and forward-looking topics. Designed to keep directors informed, aligned, and ready to advise. Use the full set for in-person quarterly meetings; trim sections for monthly checkpoints.",audienceFit:["board","directors","executives","investors"],durationRange:{minMinutes:60,maxMinutes:180},tags:["rhythm-of-business","board","governance","executive"],beats:[{id:"introduction",name:"Introduction",description:"Set the tone for the meeting and walk through the agenda in one slide. Signal which sections are for discussion versus information so directors know where their time is most valuable.",layoutHint:"title-left",instructions:"Set the tone",slideType:"text"},{id:"ceo-update",name:"CEO Update",description:"Deliver the CEO's view of the period: what changed, what mattered, where the company stands. Two or three sentences in the speaker's voice \u2014 board members read this slide first.",instructions:"Deliver company insights",slideType:"text",layoutHint:"text-1x-left"},{id:"highlights",name:"Highlights",description:"Share major successes across the business. Customer wins, launches, hires, milestones. Specific and brief; this is the slide that sets the tone, not the slide that proves the case.",instructions:"Share major successes",slideType:"text",layoutHint:"text-1x-left"},{id:"challenges",name:"Challenges",description:"Address the obstacles facing the business honestly. Boards earn their value when surfaced to real problems; under-disclosure here erodes trust faster than the problems themselves.",instructions:"Address potential obstacles",slideType:"text",layoutHint:"text-1x-left"},{id:"company-needs",name:"Company Needs",description:"Identify where the business needs the board's help: introductions, decisions, advice. Specific asks turn the meeting from a report into a working session.",instructions:"Identify support requirements",slideType:"text",layoutHint:"text-1x-left"},{id:"funnel-metrics",name:"Funnel Metrics",description:"Discuss the sales pipeline: leads, conversion, velocity, win rate. Use the metrics that match the company's current motion; resist the temptation to show the same chart you showed last quarter for continuity's sake.",instructions:"Discuss sales progress",slideType:"text",layoutHint:"text-1x-left"},{id:"engagement-metrics",name:"Engagement Metrics",description:"Analyze customer interaction: usage, retention, NPS, expansion. Show whether the product is being loved or only being bought.",instructions:"Analyze customer interaction",slideType:"text",layoutHint:"text-1x-left"},{id:"financial-metrics",name:"Financial Metrics",description:"Review fiscal health: revenue, gross margin, burn, runway, cash. One slide directors can scan in twenty seconds and trust the numbers on.",instructions:"Review fiscal health",slideType:"text",layoutHint:"text-1x-left"},{id:"performance-vs-plan",name:"Performance vs Plan",description:"Compare actuals to plan across the metrics that matter most. Variance is the slide directors will probe; show your work, name the drivers, propose adjustments.",instructions:"Compare objectives and actuals",slideType:"text",layoutHint:"text-1x-left"},{id:"org-chart",name:"Org Chart",description:"Present the team structure and any key changes since the last meeting. Directors track org evolution as a leading indicator; help them see hires, departures, and reshapes clearly.",instructions:"Present team structure",slideType:"text",layoutHint:"text-1x-left"},{id:"product-roadmap",name:"Product Roadmap",description:"Highlight the product plan and what ships when. Pair each major bet with the customer or business outcome it serves.",instructions:"Highlight future plans",slideType:"text",layoutHint:"text-1x-left"},{id:"quality",name:"Quality",description:"Showcase the product quality bar: reliability, defect rates, support outcomes. Directors take quality as a proxy for engineering culture; let the data speak.",instructions:"Showcase product's standards",slideType:"text",layoutHint:"text-1x-left"},{id:"engineering-update",name:"Engineering Update",description:"Communicate technical progress, key bets, and platform investments. Translate engineering work into business consequences directors can evaluate.",instructions:"Communicate technical progress",slideType:"text",layoutHint:"text-1x-left"},{id:"marketing-update",name:"Marketing Update",description:"Update on demand-gen, brand, and category-shaping efforts. Connect spend to pipeline and pipeline to revenue; avoid 'campaigns we ran' lists.",instructions:"Update on promotional efforts",slideType:"text",layoutHint:"text-1x-left"},{id:"business-development-update",name:"Business Development Update",description:"Speak to growth initiatives: partnerships, channels, alliances. Each entry should have a stage, an owner, and a credible upside.",instructions:"Speak on growth initiatives",slideType:"text",layoutHint:"text-1x-left"},{id:"operations-update",name:"Operations Update",description:"Discuss day-to-day operations: people ops, finance, legal, IT. Brief but explicit \u2014 directors notice when ops is missing.",instructions:"Discuss day-to-day activities",slideType:"text",layoutHint:"text-1x-left"},{id:"special-topic-1",name:"Special Topic 1",description:"Discuss the period's first deep-dive topic. This is where the board does its highest-leverage work; pose the question, show the analysis, ask for their view.",instructions:"Discuss selected subject",slideType:"text",layoutHint:"text-1x-left"},{id:"special-topic-2",name:"Special Topic 2",description:"Cover the second deep-dive topic, framed the same way. Two specials per meeting; more, and the meeting becomes a recital.",instructions:"Touch on additional topic",slideType:"text",layoutHint:"text-1x-left"},{id:"feedback",name:"Feedback",description:"Elicit the board's perspective with concrete prompts. The strength of board governance is in its candor \u2014 invite it explicitly.",instructions:"Elicit board's thoughts",slideType:"text",layoutHint:"text-1x-left"},{id:"formalities",name:"Formalities",description:"Conclude with the necessary governance items: votes, approvals, committee reports, document acknowledgments. Run them efficiently and document the outcomes.",instructions:"Conclude with necessary formalities",slideType:"text",layoutHint:"text-1x-left"},{id:"closing-remarks",name:"Closing Remarks",description:"Close with concluding observations and the agenda for the next meeting. End on a forward-looking note; directors should leave knowing what to watch.",layoutHint:"title-left",instructions:"Concluding observations",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"weekly-progress",name:"Weekly Progress",summary:"Tight rhythm-of-business arc for weekly progress reports: objectives, achievements, progress, challenges, opportunities, recognition, plan, discussion, conclusion. Designed for fifteen-to-thirty-minute team check-ins, not deep dives.",audienceFit:["managers","teams","cross-functional-partners"],durationRange:{minMinutes:15,maxMinutes:30},tags:["rhythm-of-business","weekly","internal","operations"],beats:[{id:"opening",name:"Opening",description:"Open with the initiative name, the date, and the one-line headline for the week. Frame the meeting in fifteen seconds so the rest of the time is content.",layoutHint:"title-left",instructions:"Initiative name & date",slideType:"text"},{id:"objectives",name:"Objectives",description:"State what the team set out to do this week. Specific, measurable. The audience should be able to read this slide alone and know what 'on track' would mean.",instructions:"Set the expectations",slideType:"text",layoutHint:"text-1x-left"},{id:"achievements",name:"Achievements",description:"Celebrate the week's wins. Concrete, attributable, dated. Brevity here \u2014 the meeting is for what's next, not a victory lap.",instructions:"Celebrate success",slideType:"text",layoutHint:"text-1x-left"},{id:"overall-progress",name:"Overall Progress",description:"Evaluate performance against the objectives. Use a simple status indicator (green/yellow/red) plus the leading metric. Help the audience scan the state in seconds.",instructions:"Evaluate performance",slideType:"text",layoutHint:"text-1x-left"},{id:"challenges",name:"Challenges",description:"Address what's hard right now: blockers, slipping items, surfaced risks. Tie each challenge to either an owner working it or a discussion you want this week.",instructions:"Address difficulties",slideType:"text",layoutHint:"text-1x-left"},{id:"opportunities-for-improvement",name:"Opportunities for Improvement",description:"Surface where the team can level up. Process tweaks, tooling needs, ways of working. Improvement opportunities should feel like seeds, not corrections.",instructions:"Seek growth",slideType:"text",layoutHint:"text-1x-left"},{id:"highlights-recognition",name:"Highlights & Recognition",description:"Recognize specific contributions by name. Recognition belongs in the deck, not just in the meeting \u2014 written acknowledgment travels further than verbal.",instructions:"Appreciate efforts",slideType:"text",layoutHint:"text-1x-left"},{id:"goals-next-week",name:"Goals Next Week",description:"Plan the week ahead with three to five specific goals. Each should be small enough to finish, large enough to matter, and clearly owned.",instructions:"Plan ahead",slideType:"text",layoutHint:"text-1x-left"},{id:"discussion-feedback",name:"Discussion & Feedback",description:"Open the floor with two or three prompts \u2014 decisions you need, opinions you want, blockers you'd like cleared. End the recap actively.",instructions:"Encourage input",slideType:"text",layoutHint:"text-1x-left"},{id:"conclusion",name:"Conclusion",description:"Close with one line that motivates the team into the next week. Echo the headline so the meeting feels closed.",layoutHint:"title-left",instructions:"Recap & motivate",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"status-update",name:"Status Update",summary:"Concise progress-report arc for keeping a stakeholder informed: headline, brief, progress, results, plan, feedback. Optimized for short, repeated updates rather than one-time deep dives.",audienceFit:["stakeholders","managers","customers","executives"],durationRange:{minMinutes:5,maxMinutes:15},tags:["reporting","operations","customer-relationship","weekly"],beats:[{id:"headline",name:"Headline",description:"Open with the single most important sentence the audience needs to know \u2014 on track, off track, or shifted. The headline replaces 'how's it going' with a clear answer.",layoutHint:"title-left",instructions:"Title & date",slideType:"text"},{id:"brief",name:"Brief",description:"State the objective for the period and what was promised. One slide, three lines. Frames the rest of the update so progress is read against a clear bar.",instructions:"Summary/objectives",slideType:"text",layoutHint:"text-1x-left"},{id:"progress",name:"Progress",description:"Walk through the actions taken since the last update. Specific, attributable, dated. Avoid effort theater \u2014 list outcomes and material moves, not activity for its own sake.",instructions:"Explain actions taken",slideType:"text",layoutHint:"text-1x-left"},{id:"results",name:"Results",description:"Show the outcomes those actions produced. Metrics, customer signals, decisions made. Keep the comparison crisp \u2014 versus plan, versus last period, versus benchmark.",instructions:"Show outcomes",slideType:"text",layoutHint:"text-1x-left"},{id:"action-plan",name:"Action Plan",description:"Outline the next steps and who owns them. Be specific about the next decision point and what would have to happen to slip the schedule.",instructions:"Outline next steps",slideType:"text",layoutHint:"text-1x-left"},{id:"feedback",name:"Feedback",description:"Invite the audience to weigh in: where you'd like input, where you need a decision, where help would unblock you. End the update with an open hand, not a closed file.",layoutHint:"title-left",instructions:"Ask for response",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"performance-review",name:"Performance Review",summary:"Analytical review of individual, team, or company performance grounded in metrics. Walks through results, key drivers, wins, challenges, and the adjustments that will shape the next period.",audienceFit:["leadership","managers","teams"],durationRange:{minMinutes:20,maxMinutes:60},tags:["data-driven","review","operations","metrics"],beats:[{id:"briefing",name:"Briefing",description:"Frame what this review covers: the period, the unit, the standard you're measuring against. One slide that lets the audience know exactly what they're being asked to evaluate.",layoutHint:"title-center",instructions:"Outline presentation objective",slideType:"text"},{id:"results",name:"Results",description:"Lead with the headline result. On track, ahead, or behind, and by how much. Resist softening \u2014 clear numbers up front earn credibility for the analysis that follows.",instructions:"Summarize performance findings",slideType:"text",layoutHint:"text-1x-left"},{id:"key-metrics",name:"Key Metrics",description:"Walk through the pivotal indicators. One chart per metric, clear comparison period, target or benchmark visible on the same frame. Help the audience see the data the way you do.",instructions:"Review pivotal indicators",slideType:"text",layoutHint:"text-1x-left"},{id:"team-performance",name:"Team Performance",description:"Examine collective achievements and how the team contributed. Avoid generic praise; cite specific moves and the people behind them where the audience would expect it.",instructions:"Examine collective achievements",slideType:"text",layoutHint:"text-1x-left"},{id:"highlight",name:"Highlight",description:"Spotlight one standout contribution that defined the period. A landmark deal, a launch, a fix, a hire. One vivid example sticks longer than a list of accomplishments.",instructions:"Show key contribution",slideType:"text",layoutHint:"text-1x-left"},{id:"analysis",name:"Analysis",description:"Dig under the metrics. What drove the numbers, what held them back, what's signal versus noise. Analysis is where the audience learns whether you actually understand the system you're reporting on.",instructions:"Uncover data insights",slideType:"text",layoutHint:"text-1x-left"},{id:"success",name:"Success",description:"Reinforce the past triumphs that show the system works. Briefly \u2014 the audience came for what's next, not a victory lap. Wins earn permission for the harder slides ahead.",instructions:"Reinforce past triumphs",slideType:"text",layoutHint:"text-1x-left"},{id:"challenges",name:"Challenges",description:"Name the obstacles encountered honestly. What didn't move, what regressed, what the team is still wrestling with. Understated challenges read as missed signal, not modesty.",instructions:"Highlight encountered obstacles",slideType:"text",layoutHint:"text-1x-left"},{id:"adjustments",name:"Adjustments",description:"Identify the changes you're making in response. New tactics, reallocations, sunsets. Each adjustment should map to a challenge above \u2014 adjustments without diagnosis feel arbitrary.",instructions:"Identify necessary changes",slideType:"text",layoutHint:"text-1x-left"},{id:"strategy-evolution",name:"Strategy Evolution",description:"Show how the strategy itself evolves heading into the next period. Refinements, sharpened bets, dropped initiatives. The audience should see continuity as well as change.",instructions:"Plan for improvement",slideType:"text",layoutHint:"text-1x-left"},{id:"discussion",name:"Discussion",description:"Open the floor with two or three specific prompts. End the review actively \u2014 questions you want answered, decisions you want made \u2014 so the meeting yields more than the deck.",layoutHint:"title-left",instructions:"Promote active discourse",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"survey-analysis",name:"Survey Analysis",summary:"Structured walk-through of survey results: topic, executive summary, methodology, findings, analysis, implications, recommendations. Built so a reader who only sees the second slide already knows the headline insight.",audienceFit:["executives","researchers","stakeholders","marketing-teams"],durationRange:{minMinutes:20,maxMinutes:60},tags:["data-driven","research","insights","voice-of-customer"],beats:[{id:"introduction",name:"Introduction",description:"Open by naming the question the survey was meant to answer. Why this, why now, who commissioned it. Anchor the audience in the decision the survey is designed to inform.",instructions:"Present survey topic",slideType:"text",layoutHint:"text-1x-left"},{id:"executive-summary",name:"Executive Summary",description:"State the top three findings in plain language on a single slide. A reader who only sees this slide should still be able to make the right call. Avoid hedging \u2014 synthesis is the point.",instructions:"Summarize key findings",slideType:"text",layoutHint:"text-1x-left"},{id:"context",name:"Context",description:"Detail the situation behind the survey: prior knowledge, related research, the gap this work fills. Just enough to position the findings as new information rather than restated common sense.",instructions:"Detail survey background",slideType:"text",layoutHint:"text-1x-left"},{id:"data-methodology",name:"Data & Methodology",description:"Describe how the data was collected and from whom. Sample size, recruitment, instrument, timing. Be honest about limitations; methodological transparency is what gives the findings their weight.",instructions:"Discuss sourcing and collection",slideType:"text",layoutHint:"text-1x-left"},{id:"data-summary",name:"Data Summary",description:"Give the audience an overview of the dataset before drilling in. Demographics, response rates, distribution of key variables. Help them calibrate what 'most' and 'few' mean in this study.",instructions:"Provide data overview",slideType:"text",layoutHint:"text-1x-left"},{id:"findings",name:"Findings",description:"Present the key insights one at a time. Lead each finding with the claim, then the chart. Avoid burying the point under the visualization \u2014 captions should restate the insight in words.",instructions:"Highlight key insights",slideType:"text",layoutHint:"text-1x-left"},{id:"data-analysis",name:"Data Analysis",description:"Break down the data behind each finding: cross-tabs, segment splits, statistical confidence. This is the slide skeptics will scrutinize \u2014 make it scrutinizable.",instructions:"Break down data",slideType:"text",layoutHint:"text-1x-left"},{id:"implications",name:"Implications",description:"Translate findings into 'so what.' What changes for product, marketing, ops, the customer? Implications without consequences are interesting trivia, not research.",instructions:"Discuss survey implications",slideType:"text",layoutHint:"text-1x-left"},{id:"recommendations",name:"Recommendations",description:"Provide the actions that follow from the implications. Prioritize, attach owners, mark which require decisions. This is where research becomes useful.",instructions:"Provide action plans",slideType:"text",layoutHint:"text-1x-left"},{id:"conclusion",name:"Conclusion",description:"Recap the headline finding and the most important recommendation. End with the next step \u2014 a follow-on study, a workshop, a decision \u2014 so the work doesn't sit on a shelf.",layoutHint:"title-left",instructions:"Recap and finalize",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"trend-analysis",name:"Trend Analysis",summary:"Identify and discuss data-driven patterns to understand performance and forecast what's next. Useful for market reviews, strategic outlooks, and any deck where the audience must act on a direction-of-travel call.",audienceFit:["executives","analysts","leadership"],durationRange:{minMinutes:15,maxMinutes:45},tags:["data-driven","forecasting","strategy","analysis"],beats:[{id:"introduction",name:"Introduction",description:"Open by establishing why this trend matters now. Tie it to a decision on the table or a forecast that's about to be made. Trends without consequences are filler.",instructions:"Ignite interest, establish significance",slideType:"text",layoutHint:"text-1x-left"},{id:"historical-comparison",name:"Historical Comparison",description:"Contrast current data with the relevant past. Pick the comparison window that makes the trend visible without cherry-picking. Be honest about base effects.",instructions:"Contrast current and past data",slideType:"text",layoutHint:"text-1x-left"},{id:"pattern-identification",name:"Pattern Identification",description:"Name the recurring outcome you've spotted. Use one or two strong charts that show the pattern unambiguously. Avoid overclaiming significance from a small N.",instructions:"Point out recurring outcomes",slideType:"text",layoutHint:"text-1x-left"},{id:"future-prediction",name:"Future Prediction",description:"Project where the trend leads if it continues. Show the forecast and the confidence interval. State the assumptions that would have to break for the prediction to fail.",instructions:"Predict using established patterns",slideType:"text",layoutHint:"text-1x-left"},{id:"action-plan",name:"Action Plan",description:"Translate the prediction into the strategy it implies. Specific actions, sequenced. Each action should map to a particular reading of the trend, not a generic best practice.",instructions:"Strategies based on prediction",slideType:"text",layoutHint:"text-1x-left"},{id:"implementation",name:"Implementation",description:"Walk through how the actions get executed: owners, milestones, monitoring. The audience should leave understanding what to do tomorrow, not just what to think about.",instructions:"Discuss strategy execution",slideType:"text",layoutHint:"text-1x-left"},{id:"conclusion",name:"Conclusion",description:"Recap the trend, the forecast, and the recommended action. End with the leading indicator you'll watch to know if the call is right.",layoutHint:"title-left",instructions:"Summarize key points",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"employee-review",name:"Employee Review",summary:"Constructive performance-review arc that recognizes work, gives candid feedback, and sets growth goals together. For one-on-one performance conversations and formal year-end reviews.",audienceFit:["employee","manager","hr-partner"],durationRange:{minMinutes:30,maxMinutes:60},tags:["workforce","hr","review","manager"],beats:[{id:"introduction",name:"Introduction",description:"Open with the period covered and the spirit of the conversation: collaborative, honest, growth-focused. Frame the meeting so both sides know what to expect.",layoutHint:"title-left",instructions:"Name & date",slideType:"text"},{id:"performance",name:"Performance",description:"Review job execution against the role's expectations. Specific examples, dated. Avoid characterizing the person; describe the work and its impact.",instructions:"Review job execution",slideType:"text",layoutHint:"text-1x-left"},{id:"achievements",name:"Achievements",description:"Acknowledge what went well. Name the projects, the moves, the moments where the employee made a difference. Specific recognition lands harder than generic praise.",instructions:"Acknowledge success",slideType:"text",layoutHint:"text-1x-left"},{id:"feedback",name:"Feedback",description:"Provide constructive feedback grounded in observation. Distinguish patterns from one-offs. Tell the employee something they can act on, not something they can only feel.",instructions:"Provide positive remarks",slideType:"text",layoutHint:"text-1x-left"},{id:"constructive-criticism",name:"Constructive Criticism",description:"Suggest improvements in language that respects the employee's intelligence. Pair each piece of criticism with a concrete example and a specific behavior change you'd like to see.",instructions:"Suggest improvements",slideType:"text",layoutHint:"text-1x-left"},{id:"development-opportunities",name:"Development Opportunities",description:"Highlight growth areas and the experiences that could stretch the employee. Frame development as an investment, not a fix.",instructions:"Highlight growth areas",slideType:"text",layoutHint:"text-1x-left"},{id:"goals",name:"Goals",description:"Outline next-period goals together. Specific, measurable, with explicit support. The strongest goals are co-authored, not handed down.",instructions:"Outline next steps",slideType:"text",layoutHint:"text-1x-left"},{id:"mentoring",name:"Mentoring",description:"Encourage continued learning through mentorship, training, peer pairings. Close the review with the message that growth is a shared responsibility, not a one-way evaluation.",layoutHint:"title-left",instructions:"Encourage continuous learning",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"performance-improvement-plan",name:"Performance Improvement Plan",summary:"Structured PIP arc that helps a struggling employee see expectations clearly, understand the gap, and walk into a credible improvement path. Designed to be respectful, specific, and outcome-focused \u2014 not punitive.",audienceFit:["employee","manager","hr-partner"],durationRange:{minMinutes:30,maxMinutes:60},tags:["workforce","hr","performance","manager"],beats:[{id:"introduction",name:"Introduction",description:"Begin respectfully and set a constructive tone. Be clear about what this conversation is and isn't. The opening shouldn't catastrophize or sugarcoat \u2014 clarity is kinder than either.",instructions:"Begin respectfully and positively",slideType:"text",layoutHint:"text-1x-left"},{id:"set-expectations",name:"Set Expectations",description:"Detail the level of performance expected in the role. Specific behaviors, deliverables, and standards. Expectations the employee can't quote back are expectations they can't meet.",instructions:"Detail desired performance",slideType:"text",layoutHint:"text-1x-left"},{id:"identify-problems",name:"Identify Problems",description:"Name the gap between expected and observed performance. Use specific examples and dates rather than impressions. Avoid characterizing the person; focus on the work product and the impact.",instructions:"Highlight struggles and weaknesses",slideType:"text",layoutHint:"text-1x-left"},{id:"possible-solutions",name:"Possible Solutions",description:"Suggest improvement strategies tailored to the gaps named above. Behavior changes, structural changes, support structures. Frame them as paths the employee can choose, not orders to follow.",instructions:"Suggest improvement strategies",slideType:"text",layoutHint:"text-1x-left"},{id:"offer-resources",name:"Offer Resources",description:"Make explicit what tools, coaching, training, or peer support is available. Resources demonstrate that the organization is investing in the outcome, not setting the employee up to fail.",instructions:"Propose help and tools",slideType:"text",layoutHint:"text-1x-left"},{id:"motivate-change",name:"Motivate Change",description:"Connect improvement to what the employee values: their growth, their team, their career. Inspire action without minimizing the seriousness of the situation.",instructions:"Inspire improvement action",slideType:"text",layoutHint:"text-1x-left"},{id:"follow-up",name:"Follow Up",description:"Schedule the check-ins. Frequency, format, criteria for progress. Predictable follow-up turns a PIP from a threat into a plan.",instructions:"Schedule progress check-ins",slideType:"text",layoutHint:"text-1x-left"},{id:"conclusion",name:"Conclusion",description:"Close with confidence in the path forward and a clear restatement of what success looks like. End the meeting having both raised the bar and reaffirmed the relationship.",layoutHint:"title-left",instructions:"Encourage and remind success",slideType:"text"}]},{$schema:"https://openpresentation.org/schema/opf-narrative/v1",id:"capacity-planning",name:"Capacity Planning",summary:"Workforce and operational capacity-planning arc: kickoff, urgency, current state, projection, tactics, implementation, revision, conclusion. For decks where leadership must decide whether the organization has enough resources to meet upcoming demand.",audienceFit:["leadership","operations","hr-partners","finance"],durationRange:{minMinutes:20,maxMinutes:45},tags:["workforce","operations","planning","resource-management"],beats:[{id:"kickoff",name:"Kickoff",description:"Introduce what the planning exercise covers and the decision you need from the audience. Frame the time horizon and the resources in scope so the rest of the deck stays bounded.",layoutHint:"title-center",instructions:"Introduce the topic",slideType:"text"},{id:"urgency",name:"Urgency",description:"Show why this is the right moment to plan capacity. Pipeline shifts, hiring freezes, operational stress signals. Urgency turns capacity from an annual ritual into a decision the audience leans into.",instructions:"Show needs",slideType:"text",layoutHint:"text-1x-left"},{id:"situation",name:"Situation",description:"Highlight the current resource picture: people, tools, infrastructure, vendor capacity. Show utilization, not just headcount. The audience should know where slack and stress live today.",instructions:"Highlight current resources",slideType:"text",layoutHint:"text-1x-left"},{id:"projection",name:"Projection",description:"Predict future demand under your base case and a sensitivity case. Tie demand to specific drivers \u2014 pipeline, launches, seasonality \u2014 so the audience can challenge the assumptions, not just the totals.",instructions:"Predict future demands",slideType:"text",layoutHint:"text-1x-left"},{id:"tactics",name:"Tactics",description:"Suggest the strategies for closing any gap: hiring, automation, outsourcing, prioritization. Each tactic should map to a specific demand driver and a defensible cost.",instructions:"Suggest coping strategies",slideType:"text",layoutHint:"text-1x-left"},{id:"implementation",name:"Implementation",description:"Discuss how the plan gets deployed. Sequencing, owners, dependencies, lead times. Capacity decisions slip the most when the rollout isn't planned with the same rigor as the sizing.",instructions:"Discuss deployment plans",slideType:"text",layoutHint:"text-1x-left"},{id:"revision",name:"Revision",description:"Define the leading indicators that would trigger a re-plan, and the cadence of review. Capacity plans age fast; show the audience how the plan stays alive.",instructions:"Evaluate and adjust",slideType:"text",layoutHint:"text-1x-left"},{id:"conclusion",name:"Conclusion",description:"Wrap up with the specific recommendations and the decisions you need today. End with the next checkpoint and what evidence will be on the table at it.",layoutHint:"title-left",instructions:"Wrap-up & recommendations",slideType:"text"}]}],Al=[{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"linkedin",name:"LinkedIn",summary:"Professional social network for individuals and companies.",description:"LinkedIn distinguishes between member profiles ('/in/<handle>') and company pages ('/company/<handle>'). Renderers should pick the appropriate URL pattern based on whether the parent is an Organization or a Speaker.",baseUrl:"https://linkedin.com",profileUrlPattern:"https://linkedin.com/in/{handle}",companyUrlPattern:"https://linkedin.com/company/{handle}",handlePrefix:"",handleExample:"alice-chen",brandColor:"#0A66C2",tags:["professional","default"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"x",name:"X",summary:"Real-time microblog for news, opinions, and discussion. Formerly Twitter.",description:"X uses a single profile URL pattern for both individuals and organizations. Handles are conventionally rendered with an '@' prefix.",baseUrl:"https://x.com",profileUrlPattern:"https://x.com/{handle}",handlePrefix:"@",handleExample:"@alicechen",brandColor:"#000000",tags:["microblog","news","default"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"github",name:"GitHub",summary:"Code-hosting platform for developers and organizations.",description:"GitHub uses the same URL pattern for users and organizations ('/<handle>'). Use the companyUrlPattern for organization references for symmetry with platforms that distinguish.",baseUrl:"https://github.com",profileUrlPattern:"https://github.com/{handle}",companyUrlPattern:"https://github.com/{handle}",handlePrefix:"",handleExample:"alicechen",brandColor:"#181717",tags:["developer","code"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"youtube",name:"YouTube",summary:"Video-sharing platform with creator and brand channels.",description:"YouTube channels are addressable via the '@<handle>' form. The handlePrefix is '@' but it is part of the URL itself.",baseUrl:"https://youtube.com",profileUrlPattern:"https://youtube.com/@{handle}",handlePrefix:"@",handleExample:"@acme",brandColor:"#FF0000",tags:["video","creator","brand"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"instagram",name:"Instagram",summary:"Photo and short-form video network from Meta.",baseUrl:"https://instagram.com",profileUrlPattern:"https://instagram.com/{handle}",handlePrefix:"@",handleExample:"@acme",brandColor:"#E4405F",tags:["photo","video","lifestyle"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"facebook",name:"Facebook",summary:"General-purpose social network from Meta.",baseUrl:"https://facebook.com",profileUrlPattern:"https://facebook.com/{handle}",companyUrlPattern:"https://facebook.com/{handle}",handlePrefix:"",handleExample:"acme",brandColor:"#1877F2",tags:["general","brand"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"tiktok",name:"TikTok",summary:"Short-form video network with strong recommendation feed.",description:"TikTok profiles are addressable as '@<handle>'. The handlePrefix is '@' and is included in the URL.",baseUrl:"https://tiktok.com",profileUrlPattern:"https://tiktok.com/@{handle}",handlePrefix:"@",handleExample:"@acme",brandColor:"#010101",tags:["video","short-form"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"threads",name:"Threads",summary:"Text-first social network from Meta, integrated with Instagram identity.",baseUrl:"https://threads.net",profileUrlPattern:"https://threads.net/@{handle}",handlePrefix:"@",handleExample:"@alicechen",brandColor:"#000000",tags:["microblog","text"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"mastodon",name:"Mastodon",summary:"Decentralized microblog network across federated instances.",description:"Mastodon profiles are instance-scoped: the canonical URL form is '<instance>/@<handle>' (e.g. https://hachyderm.io/@acme). The catalog cannot fix a single base URL \u2014 store full URLs as values, or '@<handle>@<instance>' as the rendered handle. The profileUrlPattern below is illustrative and assumes mastodon.social as a fallback.",baseUrl:"https://mastodon.social",profileUrlPattern:"https://mastodon.social/@{handle}",handlePrefix:"@",handleExample:"@alice@hachyderm.io",brandColor:"#6364FF",tags:["microblog","decentralized","fediverse"]},{$schema:"https://openpresentation.org/schema/opf-social-platform/v1",id:"bluesky",name:"Bluesky",summary:"Decentralized microblog network built on the AT Protocol.",description:"Bluesky handles are domain-style ('alice.bsky.social'). Profile URLs use the form 'https://bsky.app/profile/<handle>'. Renderers should pass the handle through unchanged.",baseUrl:"https://bsky.app",profileUrlPattern:"https://bsky.app/profile/{handle}",handlePrefix:"",handleExample:"alice.bsky.social",brandColor:"#1185FE",tags:["microblog","decentralized","atproto"]}],$l=[{$schema:"https://openpresentation.org/schema/opf-language/v1",id:"afrikaans",name:"Afrikaans",code:"AFR",bcp47:"af",fontScheme:"aptos",googleFontScheme:"roboto"},{$schema:"https://openpresentation.org/schema/opf-language/v1",id:"albanian",name:"Albanian",code:"SQI",bcp47:"sq",fontScheme:"aptos",googleFontScheme:"roboto"},{$schema:"https://openpresentation.org/schema/opf-language/v1",id:"amharic",name:"Amharic",code:"AMH",bcp47:"am",fontScheme:"nyala",googleFontScheme:"noto-sans-ethiopic"},{$schema:"https://openpresentation.org/schema/opf-language/v1",id:"arabic",name:"Arabic",code:"ARA",bcp47:"ar",fontScheme:"arabic-typesetting",googleFontScheme:"noto-sans-arabic"},{$schema:"https://openpresentation.org/schema/opf-language/v1",id:"armenian",name:"Armenian",code:"HYE",bcp47:"hy",fontScheme:"sylfaen",googleFontScheme:"noto-sans-armenian"},{$schema:"https://openpresentation.org/schema/opf-language/v1",id:"aymara",name:"Aymara",code:"AYM",bcp47:"ay",fontScheme:"aptos",googleFontScheme:"roboto"},{$schema:"https://openpresentation.org/s